#!/usr/bin/env tsx
/**
 * scripts/_importGraph.ts
 * Shared utilities for architecture check scripts.
 * Provides AST-based scanning for TS/TSX files with regex fallback.
 */

import * as fs from "fs";
import * as path from "path";
import * as ts from "typescript";

// ============================================================================
// Types
// ============================================================================

export interface Match {
    file: string;          // Relative path from scanRoot
    line: number;          // 1-indexed
    snippet: string;       // Trimmed line content
}

export interface ScanOptions {
    extensions?: string[]; // Default: [".ts"]
    excludeDirs?: string[]; // Default: ["node_modules", "dist"]
    excludeTests?: boolean; // Default: true
}

export interface ScanResult {
    file: string;
    matches: Match[];
}

// ============================================================================  
// Directory Scanning
// ============================================================================

/**
 * Scans a directory recursively, returning all matching file paths.
 */
export function listFiles(rootDir: string, opts: ScanOptions = {}): string[] {
    const extensions = opts.extensions ?? [".ts"];
    const excludeDirs = opts.excludeDirs ?? ["node_modules", "dist"];
    const excludeTests = opts.excludeTests ?? true;

    const results: string[] = [];

    function walk(dir: string) {
        if (!fs.existsSync(dir)) return;
        const entries = fs.readdirSync(dir, { withFileTypes: true });

        for (const entry of entries) {
            const fullPath = path.join(dir, entry.name);

            if (entry.isDirectory()) {
                if (!excludeDirs.includes(entry.name)) {
                    walk(fullPath);
                }
            } else {
                const ext = path.extname(entry.name);
                if (!extensions.includes(ext)) continue;
                if (excludeTests && entry.name.endsWith(".test.ts")) continue;
                results.push(fullPath);
            }
        }
    }

    walk(rootDir);
    return results;
}

/**
 * Normalizes path separators to forward slashes for consistent comparison.
 */
export function normalizePath(p: string): string {
    return p.replace(/\\/g, "/");
}

/**
 * Gets relative path from root with normalized separators.
 */
export function relativePath(fullPath: string, rootDir: string): string {
    return normalizePath(path.relative(rootDir, fullPath));
}

// ============================================================================
// AST Helpers
// ============================================================================

function parseFile(filePath: string): { sourceFile: ts.SourceFile; content: string } | null {
    if (!fs.existsSync(filePath)) return null;
    const content = fs.readFileSync(filePath, "utf-8");
    const sourceFile = ts.createSourceFile(
        filePath,
        content,
        ts.ScriptTarget.Latest,
        true,
        filePath.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS
    );
    return { sourceFile, content };
}

function getLineNumber(sourceFile: ts.SourceFile, pos: number): number {
    return sourceFile.getLineAndCharacterOfPosition(pos).line + 1;
}

function getLineSnippet(content: string, lineNumber: number): string {
    const lines = content.split("\n");
    return (lines[lineNumber - 1] || "").trim();
}

// ============================================================================
// AST-Based Scanners (Preferred for .ts/.tsx)
// ============================================================================

/**
 * AST-based import scanner. Returns all import/export specifiers.
 */
export function scanImportsAst(
    filePath: string,
    relativeTo?: string
): Match[] {
    const parsed = parseFile(filePath);
    if (!parsed) return [];

    const { sourceFile, content } = parsed;
    const matches: Match[] = [];
    const relPath = relativeTo ? relativePath(filePath, relativeTo) : filePath;

    function visit(node: ts.Node) {
        // import ... from "..."
        if (ts.isImportDeclaration(node) && node.moduleSpecifier) {
            const line = getLineNumber(sourceFile, node.getStart());
            matches.push({
                file: relPath,
                line,
                snippet: getLineSnippet(content, line),
            });
        }
        // export ... from "..."
        if (ts.isExportDeclaration(node) && node.moduleSpecifier) {
            const line = getLineNumber(sourceFile, node.getStart());
            matches.push({
                file: relPath,
                line,
                snippet: getLineSnippet(content, line),
            });
        }
        // require("...")
        if (ts.isCallExpression(node) &&
            ts.isIdentifier(node.expression) &&
            node.expression.text === "require") {
            const line = getLineNumber(sourceFile, node.getStart());
            matches.push({
                file: relPath,
                line,
                snippet: getLineSnippet(content, line),
            });
        }
        ts.forEachChild(node, visit);
    }

    visit(sourceFile);
    return matches;
}

/**
 * AST-based property assignment scanner.
 * Detects: obj.propertyName = ..., obj["propertyName"] = ...
 */
export function scanAssignmentsAst(
    filePath: string,
    propertyName: string,
    relativeTo?: string
): Match[] {
    const parsed = parseFile(filePath);
    if (!parsed) return [];

    const { sourceFile, content } = parsed;
    const matches: Match[] = [];
    const relPath = relativeTo ? relativePath(filePath, relativeTo) : filePath;

    function visit(node: ts.Node) {
        // BinaryExpression with = operator
        if (ts.isBinaryExpression(node) &&
            node.operatorToken.kind === ts.SyntaxKind.EqualsToken) {
            const left = node.left;

            // obj.propertyName = ...
            if (ts.isPropertyAccessExpression(left) &&
                left.name.text === propertyName) {
                const line = getLineNumber(sourceFile, node.getStart());
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
            // obj["propertyName"] = ...
            if (ts.isElementAccessExpression(left) &&
                ts.isStringLiteral(left.argumentExpression) &&
                left.argumentExpression.text === propertyName) {
                const line = getLineNumber(sourceFile, node.getStart());
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
        }
        ts.forEachChild(node, visit);
    }

    visit(sourceFile);
    return matches;
}

/**
 * AST-based identifier usage scanner.
 * Detects any usage of the identifier (import, call, reference).
 */
export function scanIdentifierUsagesAst(
    filePath: string,
    identifier: string,
    relativeTo?: string
): Match[] {
    const parsed = parseFile(filePath);
    if (!parsed) return [];

    const { sourceFile, content } = parsed;
    const matches: Match[] = [];
    const relPath = relativeTo ? relativePath(filePath, relativeTo) : filePath;
    const seenLines = new Set<number>();

    function visit(node: ts.Node) {
        if (ts.isIdentifier(node) && node.text === identifier) {
            const line = getLineNumber(sourceFile, node.getStart());
            if (!seenLines.has(line)) {
                seenLines.add(line);
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
        }
        ts.forEachChild(node, visit);
    }

    visit(sourceFile);
    return matches;
}

/**
 * AST-based function call scanner.
 * Detects: fnName(...) or obj.fnName(...)
 */
export function scanCallUsagesAst(
    filePath: string,
    fnName: string,
    relativeTo?: string
): Match[] {
    const parsed = parseFile(filePath);
    if (!parsed) return [];

    const { sourceFile, content } = parsed;
    const matches: Match[] = [];
    const relPath = relativeTo ? relativePath(filePath, relativeTo) : filePath;

    function visit(node: ts.Node) {
        if (ts.isCallExpression(node)) {
            const expr = node.expression;
            // Direct call: fnName()
            if (ts.isIdentifier(expr) && expr.text === fnName) {
                const line = getLineNumber(sourceFile, node.getStart());
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
            // Method call: obj.fnName()
            if (ts.isPropertyAccessExpression(expr) && expr.name.text === fnName) {
                const line = getLineNumber(sourceFile, node.getStart());
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
        }
        ts.forEachChild(node, visit);
    }

    visit(sourceFile);
    return matches;
}

/**
 * AST-based delete statement scanner.
 * Detects: delete obj.propertyName, delete obj["propertyName"]
 */
export function scanDeleteAst(
    filePath: string,
    propertyName: string,
    relativeTo?: string
): Match[] {
    const parsed = parseFile(filePath);
    if (!parsed) return [];

    const { sourceFile, content } = parsed;
    const matches: Match[] = [];
    const relPath = relativeTo ? relativePath(filePath, relativeTo) : filePath;

    function visit(node: ts.Node) {
        // delete expression
        if (ts.isDeleteExpression(node)) {
            const expr = node.expression;
            // delete obj.propertyName
            if (ts.isPropertyAccessExpression(expr) && expr.name.text === propertyName) {
                const line = getLineNumber(sourceFile, node.getStart());
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
            // delete obj["propertyName"]
            if (ts.isElementAccessExpression(expr) &&
                ts.isStringLiteral(expr.argumentExpression) &&
                expr.argumentExpression.text === propertyName) {
                const line = getLineNumber(sourceFile, node.getStart());
                matches.push({
                    file: relPath,
                    line,
                    snippet: getLineSnippet(content, line),
                });
            }
        }
        ts.forEachChild(node, visit);
    }

    visit(sourceFile);
    return matches;
}

// ============================================================================
// Regex-Based Scanners (Fallback)
// ============================================================================

/**
 * Scans a file for lines matching any of the provided patterns.
 * Returns matches with file, line number, and snippet.
 */
export function scanPatterns(
    filePath: string,
    patterns: RegExp[],
    relativeTo?: string
): Match[] {
    if (!fs.existsSync(filePath)) return [];

    const content = fs.readFileSync(filePath, "utf-8");
    const lines = content.split("\n");
    const matches: Match[] = [];
    const relPath = relativeTo ? relativePath(filePath, relativeTo) : filePath;

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        // Skip pure comments
        if (line.trim().startsWith("//")) continue;

        for (const pattern of patterns) {
            if (pattern.test(line)) {
                matches.push({
                    file: relPath,
                    line: i + 1,
                    snippet: line.trim(),
                });
                break; // Only report each line once
            }
        }
    }

    return matches;
}

// ============================================================================
// Unified Scanners (AST preferred, regex fallback)
// ============================================================================

function isTypeScriptFile(filePath: string): boolean {
    return filePath.endsWith(".ts") || filePath.endsWith(".tsx");
}

/**
 * Scans for property assignments. Uses AST for TS/TSX, regex fallback otherwise.
 */
export function scanAssignments(
    filePath: string,
    propertyName: string,
    relativeTo?: string
): Match[] {
    if (isTypeScriptFile(filePath)) {
        try {
            return scanAssignmentsAst(filePath, propertyName, relativeTo);
        } catch {
            // Fallback to regex on parse error
        }
    }
    const pattern = new RegExp(`(?:\\.)?${propertyName}\\s*=(?!=)`, "g");
    return scanPatterns(filePath, [pattern], relativeTo);
}

/**
 * Scans for identifier usages. Uses AST for TS/TSX, regex fallback otherwise.
 */
export function scanUsages(
    filePath: string,
    identifier: string,
    relativeTo?: string
): Match[] {
    if (isTypeScriptFile(filePath)) {
        try {
            return scanIdentifierUsagesAst(filePath, identifier, relativeTo);
        } catch {
            // Fallback to regex on parse error
        }
    }
    const pattern = new RegExp(`\\b${identifier}\\b`);
    return scanPatterns(filePath, [pattern], relativeTo);
}

/**
 * Scans for delete statements. Uses AST for TS/TSX, regex fallback otherwise.
 */
export function scanDeletes(
    filePath: string,
    propertyName: string,
    relativeTo?: string
): Match[] {
    if (isTypeScriptFile(filePath)) {
        try {
            return scanDeleteAst(filePath, propertyName, relativeTo);
        } catch {
            // Fallback to regex on parse error
        }
    }
    const pattern = new RegExp(`delete\\s+(?:\\w+\\.)?${propertyName}\\b`);
    return scanPatterns(filePath, [pattern], relativeTo);
}

/**
 * Scans for function calls. Uses AST for TS/TSX, regex fallback otherwise.
 */
export function scanCalls(
    filePath: string,
    fnName: string,
    relativeTo?: string
): Match[] {
    if (isTypeScriptFile(filePath)) {
        try {
            return scanCallUsagesAst(filePath, fnName, relativeTo);
        } catch {
            // Fallback to regex on parse error
        }
    }
    const pattern = new RegExp(`\\b${fnName}\\s*\\(`);
    return scanPatterns(filePath, [pattern], relativeTo);
}

// ============================================================================
// Batch Scanning
// ============================================================================

/**
 * Scans all files in a directory for patterns.
 */
export function scanDirectory(
    rootDir: string,
    patterns: RegExp[],
    opts: ScanOptions = {}
): ScanResult[] {
    const files = listFiles(rootDir, opts);
    const results: ScanResult[] = [];

    for (const file of files) {
        const matches = scanPatterns(file, patterns, rootDir);
        if (matches.length > 0) {
            results.push({ file: relativePath(file, rootDir), matches });
        }
    }

    return results;
}

/**
 * Checks files against allowlist, returning violations.
 */
export function checkAllowlist(
    rootDir: string,
    patterns: RegExp[],
    allowlist: Set<string>,
    opts: ScanOptions = {}
): ScanResult[] {
    const files = listFiles(rootDir, opts);
    const violations: ScanResult[] = [];

    for (const file of files) {
        const relPath = relativePath(file, rootDir);
        if (allowlist.has(relPath)) continue;

        const matches = scanPatterns(file, patterns, rootDir);
        if (matches.length > 0) {
            violations.push({ file: relPath, matches });
        }
    }

    return violations;
}

// ============================================================================
// Reporting
// ============================================================================

/**
 * Formats violations for console output.
 */
export function formatViolations(violations: ScanResult[], ruleName: string): string[] {
    const lines: string[] = [];
    for (const v of violations) {
        lines.push(`❌ ${ruleName}: ${v.file}`);
        for (const m of v.matches) {
            lines.push(`   Line ${m.line}: ${m.snippet}`);
        }
    }
    return lines;
}

#!/usr/bin/env tsx
/**
 * scripts/check-architecture.ts
 * Unified architecture guardrail runner.
 * Runs all individual check scripts and reports aggregated results.
 */

import { execSync } from "child_process";

const SCRIPTS = [
    { name: "Buff", script: "scripts/check-buffs.ts" },
    { name: "Targeting", script: "scripts/check-targeting.ts" },
    { name: "Damage", script: "scripts/check-damage.ts" },
    { name: "CardFilter", script: "scripts/check-cardfilter.ts" },
    { name: "CleanupDead", script: "scripts/check-cleanupdead.ts" },
    { name: "PendingTarget", script: "scripts/check-pendingtarget.ts" },
    { name: "EffectsRegistry", script: "scripts/check-effects-registry.ts" },
];

console.log("🏛️  Running Architecture Guardrails...\n");

let allPassed = true;
const results: { name: string; passed: boolean; output: string }[] = [];

for (const check of SCRIPTS) {
    try {
        const output = execSync(`npx tsx ${check.script}`, {
            encoding: "utf-8",
            stdio: ["pipe", "pipe", "pipe"],
        });
        results.push({ name: check.name, passed: true, output });
        console.log(`✅ ${check.name}: PASSED`);
    } catch (e: any) {
        allPassed = false;
        const output = e.stdout?.toString() || e.stderr?.toString() || e.message;
        results.push({ name: check.name, passed: false, output });
        console.log(`❌ ${check.name}: FAILED`);
        console.log(output);
    }
}

console.log("\n" + "=".repeat(50));
if (allPassed) {
    console.log("✅ All architecture checks passed.");
    process.exit(0);
} else {
    console.error("⛔ Some architecture checks failed.");
    process.exit(1);
}

#!/usr/bin/env tsx
/**
 * scripts/check-boundaries.ts
 * ─────────────────────────────────────────────────────────────────────────────
 * Enforces "core cannot import UI/DOM" architectural boundary.
 * Scans core source files and fails if forbidden imports are detected.
 * 
 * Core directories (must NOT import from UI):
 *   - src/logic/core/**
 *   - src/core/**
 *   - src/data/**
 * 
 * Forbidden import paths:
 *   - /ui/ (UI rendering layer)
 *   - /logic/browser/ (browser-only modules)
 *   - /startGame (browser-only game initialization)
 *   - /mulligan (browser-only mulligan phase)
 * 
 * Run: npx tsx scripts/check-boundaries.ts
 * ─────────────────────────────────────────────────────────────────────────────
 */

import * as fs from "fs";
import * as path from "path";

// ─────────────────────────────────────────────────────────────────────────────
// Configuration
// ─────────────────────────────────────────────────────────────────────────────

const CORE_DIRECTORIES = [
    "src/logic/core",
    "src/core",
    "src/data",
];

const FORBIDDEN_IMPORT_PATTERNS = [
    /from\s+["'][^"']*\/ui\//,              // imports from /ui/
    /from\s+["'][^"']*\/logic\/browser\//,   // imports from /logic/browser/
    /from\s+["'][^"']*\/startGame[."']/,     // imports startGame.ts (browser-only)
    /from\s+["'][^"']*\/mulligan[."']/,      // imports mulligan.ts (browser-only)
];

const FORBIDDEN_IMPORT_DESCRIPTIONS = [
    "UI layer (/ui/)",
    "Browser-only modules (/logic/browser/)",
    "Browser-only startGame module",
    "Browser-only mulligan module",
];

// ─────────────────────────────────────────────────────────────────────────────
// Utilities
// ─────────────────────────────────────────────────────────────────────────────

function getAllTsFiles(dir: string): string[] {
    const files: string[] = [];

    if (!fs.existsSync(dir)) {
        return files;
    }

    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
            files.push(...getAllTsFiles(fullPath));
        } else if (entry.isFile() && /\.tsx?$/.test(entry.name)) {
            files.push(fullPath);
        }
    }

    return files;
}

interface Violation {
    file: string;
    line: number;
    content: string;
    pattern: string;
}

function checkFile(filePath: string): Violation[] {
    const violations: Violation[] = [];
    const content = fs.readFileSync(filePath, "utf-8");
    const lines = content.split("\n");

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        if (line === undefined) continue;

        // Skip commented lines
        if (line.trim().startsWith("//")) continue;

        for (let p = 0; p < FORBIDDEN_IMPORT_PATTERNS.length; p++) {
            const pattern = FORBIDDEN_IMPORT_PATTERNS[p];
            if (pattern && pattern.test(line)) {
                violations.push({
                    file: filePath,
                    line: i + 1,
                    content: line.trim(),
                    pattern: FORBIDDEN_IMPORT_DESCRIPTIONS[p] || "unknown",
                });
            }
        }
    }

    return violations;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main
// ─────────────────────────────────────────────────────────────────────────────

function main() {
    console.log("🔍 Checking architectural boundaries...\n");
    console.log("Core directories (must NOT import from UI):");
    CORE_DIRECTORIES.forEach(d => console.log(`  - ${d}`));
    console.log("\nForbidden import paths:");
    FORBIDDEN_IMPORT_DESCRIPTIONS.forEach(d => console.log(`  - ${d}`));
    console.log("");

    const allFiles: string[] = [];
    for (const dir of CORE_DIRECTORIES) {
        allFiles.push(...getAllTsFiles(dir));
    }

    console.log(`Scanning ${allFiles.length} files...\n`);

    const allViolations: Violation[] = [];

    for (const file of allFiles) {
        const violations = checkFile(file);
        allViolations.push(...violations);
    }

    if (allViolations.length === 0) {
        console.log("✅ No boundary violations found!");
        console.log("\n   Core modules do NOT import from UI. Architecture is clean.\n");
        process.exit(0);
    } else {
        console.log(`❌ Found ${allViolations.length} boundary violation(s):\n`);

        for (const v of allViolations) {
            console.log(`  ${v.file}:${v.line}`);
            console.log(`    Forbidden: ${v.pattern}`);
            console.log(`    Line: ${v.content}`);
            console.log("");
        }

        console.log("⛔ Core modules MUST NOT import from UI.");
        console.log("   Fix the imports above before committing.\n");
        process.exit(1);
    }
}

main();

#!/usr/bin/env tsx
/**
 * scripts/check-buffs.ts
 * Enforces architectural invariants for the Buff module refactor.
 */

import * as path from "path";
import { scanPatterns } from "./_importGraph.js";

const BUFF_ROOT = path.join(process.cwd(), "src/logic/effects/ops/buff");

// Define rules
// Each rule has a file and a list of denied import patterns
const RULES = [
    {
        file: "core.ts",
        msg: "core.ts must NOT import orchestrator or facade (leaf node)",
        deny: [
            /orchestrator/,
            /ops\/buff\.ts/,
            /\.\.\/buff\.js/
        ]
    },
    {
        file: "duration.ts",
        msg: "duration.ts must NOT import orchestrator",
        deny: [
            /orchestrator/,
        ]
    },
];

function checkFile(rule: typeof RULES[0]): boolean {
    const fullPath = path.join(BUFF_ROOT, rule.file);
    const matches = scanPatterns(fullPath, rule.deny, BUFF_ROOT);

    if (matches.length > 0) {
        console.error(`❌ Rule Violation in ${rule.file}: ${rule.msg}`);
        for (const m of matches) {
            console.error(`   Line ${m.line}: ${m.snippet}`);
        }
        return false;
    }
    return true;
}

console.log("🔍 Checking Buff Module Architecture...\n");
let failure = false;

for (const rule of RULES) {
    if (!checkFile(rule)) {
        failure = true;
    }
}

if (failure) {
    console.log("\n⛔ Buff Architecture Violations Found.");
    process.exit(1);
} else {
    console.log("✅ Buff Module Constraints Passed.");
    process.exit(0);
}

#!/usr/bin/env tsx
/**
 * scripts/check-cardfilter.ts
 * Enforces architectural invariants for the CardFilter module.
 * CardFilter must remain pure (no state/effects/UI imports).
 */

import * as path from "path";
import { scanPatterns, Match } from "./_importGraph.js";

const CARDFILTER_ROOT = path.join(process.cwd(), "src/logic/core/cardFilter");

// Patterns that indicate impure imports
const IMPURE_PATTERNS = [
    /from\s+["']\.\.\/\.\.\/effects\//,      // Any import from effects/
    /gameState/,                              // State access
    /cleanup/,                                // Cleanup modules
    /adapter/,                                // UI adapter
    /targeting/,                              // Targeting modules
    /pendingTargetEffect/,                    // Selection state
    /barrier/,                                // Damage application
    /leader/,                                 // Leader damage
    /dealDamage/,                             // Damage mutation
    /applyKeyword/,                           // Keyword mutation
];

const FILES_TO_CHECK = ["types.ts", "normalize.ts", "predicates.ts"];

function checkFile(filename: string): boolean {
    const fullPath = path.join(CARDFILTER_ROOT, filename);
    const matches = scanPatterns(fullPath, IMPURE_PATTERNS, CARDFILTER_ROOT);

    if (matches.length > 0) {
        console.error(`❌ Purity violation in ${filename}:`);
        for (const m of matches) {
            console.error(`   Line ${m.line}: ${m.snippet}`);
        }
        return false;
    }

    console.log(`✓ ${filename} is pure.`);
    return true;
}

console.log("🔍 Checking CardFilter Module Architecture...");
let allPassed = true;

for (const file of FILES_TO_CHECK) {
    if (!checkFile(file)) {
        allPassed = false;
    }
}

if (allPassed) {
    console.log("✅ Architecture is clean.");
    process.exit(0);
} else {
    console.error("⛔ Architectural violations found.");
    process.exit(1);
}

#!/usr/bin/env tsx
/**
 * scripts/check-cleanupdead.ts
 * Enforces that only approved orchestrator modules may call cleanupDead.
 */

import * as path from "path";
import {
    listFiles,
    relativePath,
    scanUsages,
    formatViolations,
    ScanResult
} from "./_importGraph.js";

const SRC_ROOT = path.join(process.cwd(), "src/logic");

// Allowlist: files that may import/call cleanupDead
const ALLOWED_FILES = new Set([
    "core/cleanup.ts",
    "core/cleanup/index.ts",
    "core/turns.ts",
    "core/combat.ts",
    "core/effects/domains/combat.ts",
    "effects/ops/damage.ts",
    "effects/ops/destroy.ts",
    "effects/ops/engage.ts",
    "effects/ops/targeted/index.ts",
    "effects/ops/buff.ts",
    "effects/ops/buff/core.ts",
    "effects/ops/buff/orchestrator.ts",
