// src/core/logger.ts
import { state } from "./gameState.js";
import { GameState } from "./types.js";

/* =========================
   Stable stringify + hash
   ========================= */

const STRIP_KEYS = new Set([
    // UI/ephemeral flags that shouldn't affect game logic
    "__mulliganSelectable", "__mulliganSelected",
    "__dragging", "__hover", "__glow", "__ui",
    "potential_attack", "potential_defense",
    "_death_snapshot", "draggingId", "dropTargetId",
    "element", "el", "dom"
]);

function isPlainObject(v: any): boolean {
    return v && typeof v === "object" && !Array.isArray(v) &&
        !(v instanceof Date) && !(v instanceof Set) &&
        !(v instanceof Map) && !(v instanceof ArrayBuffer) &&
        !(ArrayBuffer.isView(v));
}

function normalizeForStable(value: any, seen: WeakSet<object>): any {
    if (value == null) return value;

    // Avoid cycles
    if (typeof value === "object" || typeof value === "function") {
        if (seen.has(value)) return "[[CYCLE]]";
        seen.add(value);
    }

    const t = typeof value;
    if (t === "function") return undefined;               // drop
    if (t === "bigint") return value.toString();         // keep deterministically
    if (value instanceof Date) return value.toISOString();

    // Typed arrays → normal arrays
    if (ArrayBuffer.isView(value)) return Array.from(value as any);

    if (value instanceof ArrayBuffer) {
        return Array.from(new Uint8Array(value));
    }

    if (Array.isArray(value)) {
        return value.map(v => normalizeForStable(v, seen));
    }

    if (value instanceof Set) {
        // sets serialized in sorted order for determinism
        const arr = Array.from(value).map(v => normalizeForStable(v, seen));
        try { arr.sort(); } catch { void 0; }
        return { "~~set": arr };
    }

    if (value instanceof Map) {
        const obj: Record<string, any> = {};
        const entries = Array.from(value.entries()).map(([k, v]) => [String(k), normalizeForStable(v, seen)]);
        entries.sort((a, b) => a[0].localeCompare(b[0]));
        for (const [k, v] of entries) obj[k] = v;
        return { "~~map": obj };
    }

    if (isPlainObject(value)) {
        const out: Record<string, any> = {};
        const keys = Object.keys(value).filter(k => !STRIP_KEYS.has(k)).sort();
        for (const k of keys) {
            const v = normalizeForStable(value[k], seen);
            if (v !== undefined) out[k] = v;
        }
        return out;
    }

    // Primitive (number/string/boolean)
    return value;
}

function stableStringify(obj: any): string {
    const normalized = normalizeForStable(obj, new WeakSet());
    return JSON.stringify(normalized);
}

/* ------------- Hashing ------------- */

// Fallback 64-bit FNV-1a (hex) for non-secure contexts
function fnv1a64Hex(str: string): string {
    let h1 = 0xCBF29CE4 ^ 0;      // low 32
    let h2 = 0x84222325 ^ 0;      // high 32 (arbitrary offset continuation)
    for (let i = 0; i < str.length; i++) {
        const c = str.charCodeAt(i);
        h1 ^= c;                     // xor into low
        // 64-bit multiply by FNV prime (0x100000001B3)
        // (emulated via 32-bit parts)
        const low = (h1 * 0x1b3) >>> 0;
        const high = (h2 * 0x1b3 + ((h1 * 0x1b3) / 2 ** 32 >>> 0)) >>> 0;
        h1 = low;
        h2 = high;
    }
    const toHex = (n: number) => n.toString(16).padStart(8, "0");
    return toHex(h2) + toHex(h1);
}

async function sha256Hex(str: string): Promise<string> {
    // Use WebCrypto if available; otherwise fallback to FNV-1a
    try {
        if (crypto?.subtle) {
            const data = new TextEncoder().encode(str);
            const buf = await crypto.subtle.digest("SHA-256", data);
            return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
        }
    } catch (_) { /* fall through */ }
    return fnv1a64Hex(str);
}

/* =========================
   Public Logger API
   ========================= */

let _id = 0;
let _mirrorToConsole = true;
let _sessionTag: string | null = null;
let _maxEntries = 10000; // safety cap
const _log: any[] = [];

/**
 * Compute a deterministic hash of the current game state.
 * Exposed in case you need ad-hoc checks.
 */
export async function computeStateHash(): Promise<string> {
    const json = stableStringify(state);
    return await sha256Hex(json);
}

/**
 * Append a log entry. Non-blocking: pushes immediately, fills hash when ready.
 * @param {string} type  Short label ("rng","play","attack","trigger","death","turn", etc.)
 * @param {object} details  Small, JSON-serializable details payload.
 * @returns {number} entry id
 */
export function logEvent(type: string, details: any = {}): number | undefined {
    if ((globalThis as any).HEADLESS) return; // <-- Add this line to silence logs in headless mode
    const id = ++_id;

    // Basic metadata snapshot (cheap)
    const meta = {
        id,
        ts: Date.now(),
        type,
        session: _sessionTag || null,
        turn: (state.roundCount ?? 0),
        isBlueTurn: !!state.isBlueTurn,
        activePlayer: state.activePlayer || (state.isBlueTurn ? "blue" : "red")
    };

    // Create shell entry immediately
    const entry = { ...meta, details, stateHash: null as string | null };
    _log.push(entry);

    // Enforce cap
    if (_log.length > _maxEntries) _log.splice(0, _log.length - _maxEntries);

    // Fill hash asynchronously and mirror to console when ready
    void computeStateHash().then(h => {
        entry.stateHash = h;
        if (_mirrorToConsole) {
            // Compact log line for readability; expand entry for full object
            console.log(`[LOG #${id}] ${type} | turn=${meta.turn} owner=${meta.activePlayer} | hash=${h}`, entry);
        }
    });

    return id;
}

/** Get a shallow copy of all log entries. */
export function getLogs(): any[] {
    return _log.slice();
}

/** Clear the in-memory log. */
export function clearLogs(): void {
    _log.length = 0;
}

/** Set a short tag for this run (e.g., seed, deck names). */
export function setSessionTag(tag: string): void {
    _sessionTag = String(tag || "");
}

/** Mirror entries to console (default: true). */
export function setConsoleMirroring(enabled: boolean): void {
    _mirrorToConsole = !!enabled;
}

/** Cap the number of kept entries (older entries are dropped). */
export function setMaxLogEntries(n: number): void {
    if (Number.isFinite(n) && n > 0) _maxEntries = n | 0;
}

/** Download logs as JSON (for repro / bug reports). */
export function downloadLogs(filename = "game_log.json"): void {
    if (typeof document === "undefined") return;
    const blob = new Blob([JSON.stringify({ session: _sessionTag, log: _log }, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
        URL.revokeObjectURL(url);
        a.remove();
    }, 0);
}

/* Optional: expose helpers to window for quick debugging */
if (typeof window !== "undefined") {
    (window as any)._gameLog = _log;
    (window as any).downloadGameLog = downloadLogs;
    (window as any).clearGameLog = clearLogs;
    (window as any).computeStateHash = computeStateHash;
    (window as any).setGameLogSession = setSessionTag;
}

// src/data/deckLoader.ts
import { state } from "../core/gameState.js";
import { drawCard, shuffleInPlace } from "../core/utils.js";
import { adapter } from "../core/adapter.js";
import { getCardDetails } from "./cardDatabase.js";
import { logEvent } from "../core/logger.js";
import { Player } from "../core/types.js";


function normalizeDeck(raw: any, deckFile?: string) {
    const expanded: any[] = [];
    const isOrdered = !!raw.ordered;

    // Testing decks: skip shuffle to preserve deterministic order
    const isTestDeck = deckFile?.toLowerCase().includes("0_testing");

    if (Array.isArray(raw)) {
        // Simple array of card objects or names
        for (const item of raw) {
            expanded.push(typeof item === "string" ? { name: item } : item);
        }
    } else if (raw && Array.isArray(raw.cards)) {
        // Object with { cards: [...], ordered: boolean }
        for (const entry of raw.cards) {
            const count = entry.count || 1;
            for (let i = 0; i < count; i++) {
                expanded.push({ ...entry, count: undefined }); // Remove count from individual instance
            }
        }
    }
    if (isOrdered || isTestDeck) {
        // We draw with deck.pop(), so reverse to make JSON[0] the first drawn.
        return expanded.reverse();
    }

    // Default: shuffle normal decks
    shuffleInPlace(expanded);
    return expanded;
}

function enrichDeck(rawDeck: any, deckFile?: string) {
    const deck = normalizeDeck(rawDeck, deckFile);
    return deck.map(card => {
        // Prefer ID lookup if available, otherwise name
        const fullData = (card.id && getCardDetails(String(card.id)))
            || getCardDetails(card.name);

        const enriched = fullData ? { ...fullData, ...card } : { ...card };
        enriched.uid = state.rng.makeUid();
        return enriched;
    });
}

async function fetchDeck(deckId: string) {
    const root = ((window as any).APP_ROOT || '/');
    // deckId may be "name", "name.json", "decks/name.json", or "/decks/name.json"
    let file = String(deckId)
        .replace(/^\/?decks\//i, '')  // strip "decks/" or "/decks/"
        .replace(/^\/+/, '');         // strip any remaining leading slash
    if (!/\.json$/i.test(file)) file += '.json';
    const url = `${root}decks/${file}`;
    const res = await fetch(url, { cache: 'no-cache' });
    if (!res.ok) throw new Error(`Deck not found at ${url}`);
    const obj = await res.json();
    obj.__deckFile = file;   // keep filename for later checks
    return obj;
}

export async function loadBlueDeck(deckName: string) {
    const loaded = await fetchDeck(deckName);
    state.blueDeckFile = loaded.__deckFile;
    const enriched = enrichDeck(loaded, loaded.__deckFile);

    state.blueDeck.length = 0;
    state.blueDeck.push(...enriched);
    state.blueHand.length = 0;
    state.blueBoard.length = 0;
    state.blueGraveyard.length = 0;

    state.blueHP = 20; state.bluePP = 1; state.blueMaxPP = 1;
    for (let i = 0; i < 4; i++) drawCard(state.blueHand, state.blueDeck);

    // Log the blue deck load
    logEvent("deckLoad", { owner: "blue", file: state.blueDeckFile, count: state.blueDeck.length });

    adapter.render();
}

export async function loadRedDeck(deckName: string) {
    const loaded = await fetchDeck(deckName);
    state.redDeckFile = loaded.__deckFile;
    const enriched = enrichDeck(loaded, loaded.__deckFile);

    state.redDeck.length = 0;
    state.redDeck.push(...enriched);
    state.redHand.length = 0;
    state.redBoard.length = 0;
    state.redGraveyard.length = 0;

    state.redHP = 20; state.redPP = 1; state.redMaxPP = 1;
    for (let i = 0; i < 4; i++) drawCard(state.redHand, state.redDeck);

    // Log the red deck load
    logEvent("deckLoad", { owner: "red", file: state.redDeckFile, count: state.redDeck.length });

    adapter.render();
}

import { Effect, EffectOp } from "../../core/types.js";
import { makeEffect } from "../../logic/core/effects/build.js";

interface CompiledOutput {
    keywords: string[];
    fanfare: Effect[];
    lastWords: Effect[];
    spell: Effect[];
    unresolved: string[];
}

const KEYWORDS = ["Storm", "Rush", "Ward", "Bane", "Drain", "Snipe", "Intimidate"];

export function compileCardText(text: string, type: string): CompiledOutput {
    const output: CompiledOutput = {
        keywords: [],
        fanfare: [],
        lastWords: [],
        spell: [],
        unresolved: []
    };

    if (!text) return output;

    // Normalize text: split by newlines or "Fanfare:", "Last Words:" markers
    // This is a naive parser. A full parser would tokenise.
    // We'll treat the text as specific sections.

    // 1. Extract global keywords (simple check)
    // Example: "Storm. Fanfare: ..."
    // We'll remove found keywords from text to avoid re-parsing them as unresolved clauses?
    // Actually, keywords usually appear independently or at start.

    const remainingText = text;

    for (const kw of KEYWORDS) {
        // Match whole word, case insensitive? distinct keyword usually capitalized.
        // "Storm." or "Storm" or "Ward,"
        const regex = new RegExp(`\\b${kw}\\b`, "i");
        if (regex.test(remainingText)) {
            // Capitalize for standard storage
            output.keywords.push(kw);
            // Optional: remove it? "Storm." -> ""
            // For now, let's leave it, but we might get "Storm" as unresolved if we don't have a pattern.
            // Let's rely on line parsing.
        }
    }

    // 2. Parse sections
    // Simple state machine
    let currentSection: "spell" | "fanfare" | "last_words" = type === "Spell" ? "spell" : "spell"; // Default to spell for Spells, for Followers text without prefix is usually passive or unhandled.
    // Actually, for Followers, lines without "Fanfare:" prefix are often traits or passives.

    // Split into sentences/clauses.
    // Splitting by period or newline.
    const chunks = text.split(/(?:\r?\n|(?<=\.)\s+)/).map(s => s.trim()).filter(Boolean);

    for (let i = 0; i < chunks.length; i++) {
        const rawChunk = chunks[i];
        if (rawChunk === undefined) continue;
        let chunk: string = rawChunk;

        // Detect Section Headers
        if (/^Fanfare:?/i.test(chunk)) {
            currentSection = "fanfare";
            chunk = chunk.replace(/^Fanfare:?\s*/i, "");
        } else if (/^Last Words:?/i.test(chunk)) {
            currentSection = "last_words";
            chunk = chunk.replace(/^Last Words:?\s*/i, "");
        }

        if (!chunk) continue;

        // Skip keywords if they are the only thing in the chunk (already handled)
        const isJustKeyword = KEYWORDS.some(kw => new RegExp(`^${kw}\\.?$`, "i").test(chunk));
        if (isJustKeyword) continue;

        // Compile Effect
        const effect = parseEffect(chunk);
        // console.log(`[Compiler] Parsing chunk: "${chunk}" ->`, effect);

        if (effect) {
            if (currentSection === "fanfare") output.fanfare.push(effect);
            else if (currentSection === "last_words") output.lastWords.push(effect);
            else if (type === "Spell") output.spell.push(effect);
            else output.unresolved.push(chunk); // Passive text on follower not supported yet
        } else {
            output.unresolved.push(chunk);
        }
    }

    return output;
}

function parseEffect(clause: string): Effect | null {
    // 1. Draw
    // "Draw a card." / "Draw 2 cards."
    const drawMatch = clause.match(/^Draw (\d+|a) cards?\.?$/i);
    if (drawMatch) {
        const matchVal = drawMatch[1];
        const count = matchVal?.toLowerCase() === "a" ? 1 : parseInt(matchVal ?? "1");
        return makeEffect("draw", { count });
    }

    // 2. Deal Damage
    // "Deal X damage to an enemy follower."
    // "Deal X damage to the enemy leader."
    const dmgMatch = clause.match(/^Deal (\d+) damage(?: to (an enemy follower|the enemy leader))?\.?$/i);
    if (dmgMatch) {
        const amt = parseInt(dmgMatch[1] ?? "0");
        const targetStr = (dmgMatch[2] ?? "").toLowerCase();
        // Map target string to conventions (if resolveTarget supports them)
        // Our engine usually requires explicit selection or random.
        // "Deal X to an enemy follower" usually implies target SELECTION if not "random".
        // The prompt said: "Deal X damage to an enemy follower." -> op damage amount X target enemy follower
        // I'll stick to a generic "damage" op and assume "target" property handles the selector string.
        // But `resolveTarget` needs `select` op usually.
        // If it's targeted play, it's usually `op: "damage", amount: X` nested inside `op: "select"`.
        // For v1, let's mapping to a flat object as requested, marking ambiguity.

        if (targetStr.includes("follower")) {
            // Targeted? implied by "an enemy follower".
            return {
                op: "select",
                target: "enemy_follower",
                effects: [makeEffect("damage", { amount: amt })]
            };
        } else if (targetStr.includes("leader")) {
            return makeEffect("damage_follower_or_leader", { amount: amt, target: "enemy_leader" });
        } else {
            // Implicit / Generic
            // "Deal X damage." -> Default to simple damage op?
            return makeEffect("damage", { amount: amt });
        }
    }

    // 3. Summon
    // "Summon a <Name>." / "Summon 2 <Name>s."
    const summonMatch = clause.match(/^Summon (\d+|a|an) (.+?)(?:s)?\.?$/i);
    if (summonMatch) {
        const countStr = (summonMatch[1] ?? "a").toLowerCase();
        const count = (countStr === "a" || countStr === "an") ? 1 : parseInt(countStr);
        const name = summonMatch[2] ?? "Unknown"; // Clean up plurals? "Knight" vs "Knights"
        // Heuristic: remove trailing 's' if not part of name? Name matching is hard.
        // Assuming user provides singular names or we fix later.

        return makeEffect("summon_named", { name, count });
    }

    // 4. Spellboost
    // "Spellboost: Subtract 1 from the cost of this card."
    if (/^Spellboost: Subtract 1 from the cost of this card\.?$/i.test(clause)) {
        return makeEffect("spellboost_hand", {}); // technically this is the effect OF spellboost, usually "spellboost" op is triggers.
        // But standardized logic often just marks "Spellboost" keyword.
        // Prompt said: "Spellboost" mentions -> keyword + op mapping where applicable.
        // For cost reduction:
        return makeEffect("reduce_cost_self", { amount: 1 });
    }

    // "Spellboost: Deal 1 more damage."
    // This implies a variable damage op.
    if (/^Spellboost: Deal 1 more damage\.?$/i.test(clause)) {
        return makeEffect("damage", { amount: "spellboost" }); // Simplified representation
    }

    return null;
}

