} from "../../../effects/ops/damage.js";
import {
    handleDestroy, handleDestroyHighest, destroyAlliedAmulets,
    handleDestroyAll, handleDestroyRandom, resolveDestroy
} from "../../../effects/ops/destroy.js";
import {
