/**
 * Triggers fanfare effects for a card.
 * @param {object} card - The card with potential fanfare effects.
 * @param {string} owner - "blue" or "red".
 */
export function onFanfare(card: CardInstance, owner: Player) {
    const list = card.fanfare || [];
    if (Array.isArray(list) && list.length) runEffects([...list], owner, card);
}

export function getEffectiveCost(card: CardInstance) {
    if (typeof card.effectiveCost === 'number' && Number.isFinite(card.effectiveCost)) return card.effectiveCost;
    const base = parseInt(card?.cost as string, 10) || 0;
    const mod = parseInt((card as any)?.cost_mod, 10) || 0;
    return base + mod;
}

// Notify (event-only) that a Loot spell was played.
// Keeps evolveEffects generic; cards listen via triggers (event: "loot_played").
function notifyLootPlayed(owner: Player, sourceCard: CardInstance | null) {
    if (!sourceCard) return;
    const isLoot =
        Array.isArray(sourceCard.tribes) &&
        sourceCard.tribes!.some(t => String(t).toLowerCase() === "loot");
    if (!isLoot) return;
    fireTrigger("loot_played", owner, { source: "play", kind: "loot", playedCard: sourceCard });
}

// Helper: Dispatch effect with strict types
function dispatchEffect<K extends EffectOp>(op: K, eff: Effect, ctx: EffectCtx): EffectResult | void {
    if (eff.op !== op) return; // Should not happen if confirmed 'eff.op'
    const handler = getOp(op);
    if (!handler) {
        throw new Error(`UNKNOWN EFFECT OPERATION: ${op}`);
    }
    // We cast strictly to 'EffectByOp[K]' which is safe because we verified op === K
    return handler(eff as EffectByOp[K], ctx);
}

// --- The Master Effect Runner ---

/**
 * Main effect dispatcher. Processes a queue of effects sequentially.
 * @param {Array<object>} effects - Array of effect objects to process.
 * @param {string} owner - "blue" or "red".
 * @param {object|null} sourceCard - The card initiating the effects.
 * @param {object} [context={}] - Shared context for targeting and chaining.
 */
export function runEffects(effects: Effect[], owner: Player, sourceCard: CardInstance | null, context?: any) {
    guardLifecycle("runEffects");

    // Runtime Assertion: Registry must be sealed
    void import("./registry.js").then(({ isRegistrySealed }) => {
        if (!isRegistrySealed()) {
            throw new Error("[Dispatcher] CRITICAL: Attempted to run effects before registry was sealed.");
        }
    });

    if (!effects) return;

    // Runtime Assertion: Queue must be an array
    if (!Array.isArray(effects)) {
        throw new Error("[Dispatcher] Invalid effects queue: expected array.");
    }

    if (effects.length === 0) return;

    const queue = [...effects]; // Shallow copy to process

    // Trace: dispatch_start
    // Access trace from context if available, or fall back to global trace (for replay injection)
    const trace = context?.trace ?? getGlobalTrace();
    if (trace) trace.emit({ kind: "dispatch_start", queueSize: queue.length });

    let processedCount = 0;

    while (queue.length > 0) {
        const eff = queue.shift()!;

        // Runtime Assertion: Op must be valid string
        if (!eff.op || typeof eff.op !== "string") {
            throw new Error(`[Dispatcher] Invalid operation: ${JSON.stringify(eff)} in card ${sourceCard?.name || "unknown"}`);
        }

        recordEvent({ type: "run_effect", payload: { op: eff.op, owner, source: sourceCard?.name } });

        // Trace: effect_start
        if (trace) trace.emit({ kind: "effect_start", op: eff.op, depth: 0 }); // Depth not tracked yet

        // Build context for the handler
        const ctx: EffectCtx = {
            state,
            owner,
            sourceCard,
            queue,
            context,
            adapter,
            trace // Pass it down
        };

        try {
            const result = dispatchEffect(eff.op, eff, ctx);

            // Protocol: "pending" stops the queue. Anything else continues.
            // We do not wait for Promises (fire-and-forget for animations/async side effects),
            // UNLESS the handler explicitly paused by returning "pending".
            if (result === "pending") {
                // Trace: effect_pending
                if (trace) trace.emit({ kind: "effect_pending", op: eff.op });

                // Paused execution (e.g. targeting waiting for input)
                // The queue state is preserved in the closure references if passed to targeting,
                // otherwise it is lost here (which is correct for "pause").
                return;
            }

            // Trace: effect_end
            if (trace) trace.emit({ kind: "effect_end", op: eff.op });
            processedCount++;

        } catch (e) {
            // Contextualize error
            const err = e instanceof Error ? e : new Error(String(e));
            err.message = `[Dispatcher] Error in op '${eff.op}': ${err.message}`;
            throw err;
        }
    }

    // Trace: dispatch_end
    if (trace) trace.emit({ kind: "dispatch_end", processed: processedCount, remaining: queue.length });
}

// --- Dependency Injection Registration ---
// Register runEffects with cleanup.ts so Last Words can trigger
registerRunEffectsInCleanup(runEffects);
// Register runEffects with triggers/process.ts so board/hand triggers can execute effects
registerRunEffects(runEffects);

import { CardInstance, Player } from "../../../core/types.js";
import { normalizeKeywordName, KeywordName } from "./registry.js";
import { getKS } from "./internal.js";
import { grantBarrier } from "../barrier.js";
import { state } from "../../../core/gameState.js";

interface KeywordOptions {
    [key: string]: any;
}

export const KEYWORD_MAP: { [key: string]: (c: CardInstance, opts?: KeywordOptions) => void } = {
    max_damage_cap: (c, opts) => {
        if (opts && typeof opts.amount === 'number') {
            getKS(c).maxDamageCap = opts.amount;
        }
    },
    rush: (c) => {
        c.hasRush = true;

        // Make sure it can actually attack right now
        if (c.attacks_left == null) {
            const per = Number.isFinite(c.attacks_per_turn) ? (c.attacks_per_turn as number) : 1;
            c.attacks_left = per;
        }
        c.can_attack = true;
        getKS(c).can_attack_followers = true;
        c.isRush = !c.hasStorm && !!c.justPlayed;
    },
    storm: (c) => {
        c.hasStorm = true;
        c.can_attack = true;
        getKS(c).can_attack_followers = true;
        c.isRush = false;
    },
    ward: (c) => { c.hasWard = true; },
    bane: (c) => { c.hasBane = true; },
    drain: (c) => { c.hasDrain = true; },
    intimidate: (c) => { c.hasIntimidate = true; },
    ambush: (c) => { c.hasAmbush = true; },
    barrier: (c, opts) => {
        grantBarrier(c, opts?.charges ?? 1);
        getKS(c).hasBarrier = true;
    },
    banish_on_death: (c) => { getKS(c).banishOnDeath = true; },
    countdown: (c, opts) => {
        c.hasCountdown = true;
        const v = Number(opts?.turns ?? opts?.count);
        if (Number.isFinite(v)) {
            c.countdown = v;
        } else if (c.countdown == null) {
            c.countdown = 0;
        }
    },
    aura: (c) => {
        c.hasAura = true;
    },
    last_words: (c, opts) => {
        c.hasLastWords = true;
        const ks = getKS(c);

        if (opts && Array.isArray(opts.effects)) {
            ks.lastWordsEffects = opts.effects;
        } else if (!ks.lastWordsEffects && !c.lastWordsEffects) {
            ks.lastWordsEffects = [];
        }
    },
    cant_be_destroyed: (c) => {
        getKS(c).cannotBeDestroyed = true;
    },
    trigger: (c, opts) => {
        if (!opts?.trigger) return;
        const ks = getKS(c);
        if (!Array.isArray(ks.triggers)) ks.triggers = [];
        ks.triggers.push(opts.trigger);
    },
    rally: (c, opts) => {
        const ks = getKS(c);
        ks.hasRally = true;
        const need = Number(opts?.count ?? 0);

        if (need > 0 && opts && Array.isArray(opts.effects)) {
            ks.rallyRequirement = need;
            ks.rallyEffects = opts.effects;
        }
    },
    fanfare: (c, opts) => {
        getKS(c).hasFanfare = true;
        c.fanfare = Array.isArray(opts?.effects) ? opts.effects : [];
    },
    strike: (c, opts) => {
        const ks = getKS(c);
        ks.hasStrike = true;
        ks.strikeEffects = Array.isArray(opts?.effects) ? opts.effects : [];
    },
    engage: (c, opts) => {
        if (!opts) return;
        c.hasEngage = true;
        const ks = getKS(c);
        ks.engageEffects = Array.isArray(opts.effects) ? opts.effects : [];
        ks.engageCost = Number(opts.cost ?? 0);
        ks.engageOncePerTurn = opts.once_per_turn !== false;
    },
    enhance: (c, opts) => {
        if (!opts?.cost) return;
        if (!c.enhanceTiers) c.enhanceTiers = [];
        c.enhanceTiers.push({ cost: Number(opts.cost), effects: opts.effects || [] });
        c.enhanceTiers.sort((a, b) => b.cost - a.cost);
    },
    spellboost: (c, opts) => {
        if (!opts) return;
        const ks = getKS(c);
        ks.hasSpellboost = true;
        ks.spellboostCount = ks.spellboostCount ?? 0;

        ks.spellboost = {
            reduceCostBy: Number(opts.reduce_cost_by ?? 1),
            minCost: Number(opts.min_cost ?? 0),
        };
    },
    counter: (c, opts) => {
        if (!opts?.key) return;
        const ks = getKS(c);
        if (!ks.counters) ks.counters = {};
        const key = String(opts.key);
        const add = Number(opts.count ?? 0);
        ks.counters[key] = (ks.counters[key] || 0) + add;
    },
    skybound_art: (c) => { },
    pixie_enter: (c, opts) => {
        const ks = getKS(c);
        ks.hasPixieEnter = true;
        ks.pixieEnterEffects = Array.isArray(opts?.effects) ? opts.effects : [];
    },
    bleed: (c, opts) => {
        const toLeader = Number(opts?.to_leader ?? 1);
        const toSelf = Number(opts?.to_self ?? 2);
        const ks = getKS(c);

        ks.hasBleed = true;
        ks.bleed = { toLeader, toSelf };
    },
    ally_enter: (c, opts) => {
        const ks = getKS(c);
        ks.hasAllyEnter = true;
        ks.allyEnterEffects = Array.isArray(opts?.effects) ? opts.effects : [];
    },
    cant_attack: (c, opts) => {
        const ks = getKS(c);
        ks.hasCantAttack = true;
        ks.cantAttack = true;
        ks.cantAttackFollowers = true;
        ks.cantAttackLeaders = true;

        if (opts?.expires_on_turn != null) {
            ks.cantAttackExpiresOnTurn = Number(opts.expires_on_turn);
            ks.cantAttackIsTemporary = true;
        }
        if (opts?.until_opponent_eot) {
            ks.cantAttackUntilOpponentEOT = true;
            ks.cantAttackIsTemporary = true;
            const isBlue = state.blueBoard.includes(c);
            const isRed = state.redBoard.includes(c);
            ks.cantAttackOwner = isBlue ? "blue" : (isRed ? "red" : (c as any).cantAttackOwner || null);
        }
    },
};

let __initializingKeywords = false;

export function applyKeyword(card: CardInstance, keywordName: string, options?: KeywordOptions) {
    if (!card || !keywordName) return;
    const key = normalizeKeywordName(keywordName);
    if (!key) {
        console.warn(`[Keywords] Unknown/Empty keyword: '${keywordName}'`);
        return;
    }
    const keywordHandler = KEYWORD_MAP[key];

    if (keywordHandler) {
        keywordHandler(card, options);

        const isTempCantAttack =
            (key === "cant_attack") && (options?.until_opponent_eot || options?.expires_on_turn);

        if (!__initializingKeywords && !isTempCantAttack) {
            if (Array.isArray(card.keywords)) {
                card.keywords = card.keywords.map(k => (typeof k === "string" ? k : { ...k }));
            } else {
                card.keywords = [];
            }

            const hasAlready = card.keywords.some(k =>
                (typeof k === "string" && normalizeKeywordName(k) === key) ||
                (k && typeof k === "object" && normalizeKeywordName(k.name || "") === key)
            );
            if (!hasAlready) (card.keywords as any[]).push(key);
        }
    } else {
        console.warn(`[Keywords] Unknown keyword: '${key}'`);
    }
}

export function applyKeywordsFromList(card: CardInstance) {
    if (!Array.isArray(card.keywords)) return;
    const snapshot = card.keywords.slice();
    __initializingKeywords = true;
    for (const k of snapshot) {
        if (typeof k === "string") {
            applyKeyword(card, k);
        } else if (k && typeof k.name === "string") {
            applyKeyword(card, k.name, k);
        }
    }
    __initializingKeywords = false;
}

import { CardInstance, Effect, Player } from "../../../core/types.js";
import { normalizeKeywordName, KeywordName } from "./registry.js";
import { getKS } from "./internal.js";
import { state } from "../../../core/gameState.js"; // Needed for resolving owner in temporary lock clearing (maybe extract context?)

// Helper to clear the lock flags on a single card
export function clearCantAttack(card: CardInstance) {
    if (!card || !card.keywordState) return;
    const ks = card.keywordState;
    delete ks.hasCantAttack;
    delete ks.cantAttack;
    delete ks.cantAttackFollowers;
    delete ks.cantAttackLeaders;
    delete ks.cantAttackUntilOpponentEOT;
    delete ks.cantAttackExpiresOnTurn;
    delete ks.cantAttackIsTemporary;
    delete ks.cantAttackOwner;
}

export function removeKeywordFromSingleCard(target: CardInstance, rawKeyword: string) {
    const normalizedRaw = normalizeKeywordName(rawKeyword);
    const keywordToRemove = normalizedRaw || rawKeyword.toLowerCase();

    if (!keywordToRemove) return;

    // Step 1: Disable the keyword's functionality (flags)
    if (keywordToRemove === "ward") target.hasWard = false;
    else if (keywordToRemove === "rush") target.hasRush = false;
    else if (keywordToRemove === "storm") target.hasStorm = false;
    else if (keywordToRemove === "bane") target.hasBane = false;
    else if (keywordToRemove === "intimidate") target.hasIntimidate = false;
    else if (keywordToRemove === "drain") target.hasDrain = false;
    else if (keywordToRemove === "last_words") target.hasLastWords = false; // Canonical key
    else if (keywordToRemove === "ambush") target.hasAmbush = false;

    // Step 2: Remove from KeywordState if applicable
    if (target.keywordState) {
        const ks = target.keywordState;
        // Logic to clear specific keyword state bits could be expanded here if needed
        // Currently most KS properties are set/added but not explicitly cleared individually unless 'remove all' triggers
    }

    // Step 3: Remove the keyword from the card's data array to fix the UI
    if (Array.isArray(target.keywords)) {
        target.keywords = target.keywords.filter(k => {
            const kwName = (typeof k === "string" ? k : (k as any)?.name) || "";
            return normalizeKeywordName(kwName) !== keywordToRemove;
        });
    }
}

export function removeAllAbilitiesFromCard(card: CardInstance) {
    // Clear boolean flags
    card.hasRush = false;
    card.hasStorm = false;
    card.hasWard = false;
    card.hasBane = false;
    card.hasDrain = false;
    card.hasAmbush = false;
    card.hasIntimidate = false;
    card.hasLastWords = false;

    card.hasAura = false;

    // Clear complex properties in KeywordState
    if (card.keywordState) {
        const ks = card.keywordState;
        ks.hasBarrier = false;

        ks.triggers = [];
        ks.hasFanfare = false;

        card.fanfare = []; // Clear root fanfare

        ks.lastWordsEffects = [];
        ks.strikeEffects = [];
        ks.engageEffects = [];

        card.enhanceTiers = [];

        // Clear Cant Attack
        clearCantAttack(card);
    }
}

