import { CardInstance, Player } from "../../../core/types.js";

export type PlayOutcome =
    | { kind: "blocked"; reason?: string }
    | { kind: "paused" }          // selection/targeting requested by effects
    | { kind: "done" };

export interface PlayedHistoryEntry {
    id: string;
    uid: string;
    name: string;
    type: string;
    cost: number;
    base_image?: string | null;
    ts: number;
}

import { GameState, PlayerAction } from "../../core/types.js";
import { EffectTraceEvent, createArrayTrace } from "./effects/trace.js";
import { EffectCtx } from "./effects/registry.js";


// We will use PlayerAction as the Action type
type Action = PlayerAction;

// --- 1. Types ---

export interface ReplayCapsule {
    version: string;
    seed: number;
    initial: { stateHash: string };
    actions: readonly Action[];
    trace: readonly EffectTraceEvent[];
    final: { stateHash: string };
}

export interface ReplayConfig {
    version: string;
    seed: number;
    actions: readonly Action[];
    // Initial state creator. 
    // If not provided, the runner assumes the caller has already set up the global state 
    // or provides a way to reset it. 
    // However, strictly following the prompt: "init?: (seed: number) => GameState"
    init?: (seed: number) => GameState;

    // The engine's action dispatcher. Must be injected to avoid circular deps.
    // It takes the current state and an action, applies it, and returns the (possibly mutated) state.
    applyAction: (state: GameState, action: Action, traceCtx?: { trace: ReturnType<typeof createArrayTrace>['sink'] }) => GameState;

    traceDepth?: boolean;
}

// --- 2. Stable Hashing (FNV-1a) ---

const FNV_OFFSET_BASIS_32 = 2166136261;
const FNV_PRIME_32 = 16777619;

function fnv1a(str: string): number {
    let hash = FNV_OFFSET_BASIS_32;
    for (let i = 0; i < str.length; i++) {
        hash ^= str.charCodeAt(i);
        hash = Math.imul(hash, FNV_PRIME_32);
    }
    return hash >>> 0;
}

function stableStringify(obj: any): string {
    if (obj === null || typeof obj !== "object") {
        return JSON.stringify(obj);
    }

    if (Array.isArray(obj)) {
        return "[" + obj.map(stableStringify).join(",") + "]";
    }

    // Object: sort keys
    const keys = Object.keys(obj).sort();
    const parts = keys.map(k => {
        const val = obj[k];
        // Skip undefined to match JSON behavior (mostly) or include explicitly?
        // JSON.stringify skips undefined values in objects.
        if (val === undefined) return "";
        return JSON.stringify(k) + ":" + stableStringify(val);
    }).filter(p => p !== "");

    return "{" + parts.join(",") + "}";
}

export function computeStateHash(gameState: GameState): string {
    // We hash specific critical slices of state to avoid enormous strings if possible,
    // or we hash the whole thing if it's reasonable. For safety and completeness,
    // we'll hash the structured shape.

    // To avoid circular structures or irrelevant UI state, we might select fields.
    // For this generic implementation, we assume GameState is largely data.
    // If GameState has methods or circular refs, this will fail. 
    // Assuming GameState types define data-data.

    // We'll strip known non-serializable or noisy fields if necessary.
    // For now, stableStringify everything.
    const str = stableStringify(gameState);
    const hash = fnv1a(str);
    return hash.toString(16);
}

// --- 3. Runner ---

/**
 * Deterministic Replay Runner.
 * 
 * Usage Example:
 * ```ts
 * import { runWithReplay } from "./replay.js";
 * import { dispatchAction } from "../../mainDispatch.js"; // your engine
 * import { resetGameState } from "../../../core/gameState.js";
 * 
 * const capsule = runWithReplay({
 *   version: "1.0.0",
 *   seed: 12345,
 *   actions: myActions,
 *   init: (seed) => resetGameState({ seed }), // ensure this returns/sets state
 *   applyAction: (s, a, ctx) => {
 *      // ensure your dispatcher can accept the trace sink in context!
 *      // if dispatchAction uses runEffects, pass { trace: ctx?.trace } to it.
 *      return dispatchAction(s, a, { trace: ctx?.trace });
 *   }
 * });
 * ```
 */
export function runWithReplay(cfg: ReplayConfig): ReplayCapsule {
    // 1. Initialize State
    let currentState: GameState;
    if (cfg.init) {
        currentState = cfg.init(cfg.seed);
    } else {
        // Fallback: If no init provided, we assumes the user has set up state externally
        // OR we might throw. The prompt suggests wrapping "resetGameState".
        // Use a safe default if possible, or demand init. 
        // We'll assume the caller *must* provide init to be safe about seeding logic.
        throw new Error("[Replay] 'init' function is required to ensure correct seeding.");
    }

    const initialHash = computeStateHash(currentState);

    // 2. Setup Trace
    const { sink, events } = createArrayTrace();

    // 3. Apply Actions
    for (const action of cfg.actions) {
        // The applyAction wrapper is responsible for plumbing the sink into the engine.
        currentState = cfg.applyAction(currentState, action, { trace: sink });
    }

    const finalHash = computeStateHash(currentState);

    return {
        version: cfg.version,
        seed: cfg.seed,
        initial: { stateHash: initialHash },
        actions: cfg.actions,
        trace: events,
        final: { stateHash: finalHash }
    };
}

// src/logic/core/replayInit.ts
// ─────────────────────────────────────────────────────────────────────────────
// REPLAY-ONLY GAME INITIALIZATION - Core-safe, no UI, no fetch
// This provides deterministic game state with real cards for replay scenarios.
// ─────────────────────────────────────────────────────────────────────────────

import { state, resetGameState, resetStateInstance } from "../../core/gameState.js";
import { CardInstance, GameState, Player } from "../../core/types.js";
import { drawCard } from "../../core/utils.js";
import { getCardDetails, isCardDatabaseInitialized } from "../../data/cardIndex.js";

// ─────────────────────────────────────────────────────────────────────────────
// Replay Deck Definitions - Using real card names from the database
// ─────────────────────────────────────────────────────────────────────────────

/**
 * A replay deck is a list of card names.
 * Cards are looked up from the card database.
 */
export interface ReplayDeckDef {
    id: string;
    cards: readonly string[];
}

// Standard test deck using real cards that exist in the database
// These are stable, simple cards for testing basic mechanics
const REPLAY_DECK_STANDARD: ReplayDeckDef = {
    id: "standard",
    cards: [
        // Low cost followers (1-2 PP) - RESTORED ORDER
        "Goblin", "Goblin", "Goblin", "Goblin", "Goblin",
        "Goblin", "Goblin", "Goblin", "Goblin", "Goblin",
        "Goblin", "Goblin", // Replaced Water Fairy
        "May, Journey Elf",
        "May, Journey Elf",
        "Flashstep Quickblader",
        "Flashstep Quickblader",
        "Indomitable Fighter",
        "Indomitable Fighter",
        // Mid cost (3 PP)
        "Vigilant Detective",
        "Vigilant Detective",
        "Vigilant Detective",
        // Spells
        "Bug Alert",
        "Bug Alert",
        "Foresight",
        // Higher cost
        "Centaur Centurion",
        "Centaur Centurion",
        "Silvercloud Dragonrider",
    ]
};

// Spell-heavy deck for testing spell mechanics
const REPLAY_DECK_SPELL_HEAVY: ReplayDeckDef = {
    id: "spell_heavy",
    cards: [
        "Bug Alert",
        "Bug Alert",
        "Foresight",
        "Goblin",
        "Goblin",
        "May, Journey Elf",
        "May, Journey Elf",
        "Flashstep Quickblader",
        "Indomitable Fighter",
        "Vigilant Detective",
        "Silvercloud Dragonrider",
    ]
};

const REPLAY_DECKS: Record<string, ReplayDeckDef> = {
    standard: REPLAY_DECK_STANDARD,
    spell_heavy: REPLAY_DECK_SPELL_HEAVY,
};

// ─────────────────────────────────────────────────────────────────────────────
// Deck Building
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Build a deck from card names.
 * Each card gets a unique UID from the seeded RNG.
 */
function buildDeckFromNames(cardNames: readonly string[], rng: any, strict: boolean = false): CardInstance[] {
    const deck: CardInstance[] = [];
    const missing: string[] = [];

    for (const name of cardNames) {
        const template = getCardDetails(name);
        if (!template) {
            if (strict) {
                missing.push(name);
            } else {
                console.warn(`[ReplayInit] Card not found: "${name}" - skipping`);
            }
            continue;
        }

        // Create card instance with unique UID
        const card: CardInstance = {
            ...template,
            uid: rng.makeUid()
        } as CardInstance;

        deck.push(card);
    }

    if (strict && missing.length > 0) {
        const uniqueMissing = [...new Set(missing)];
        throw new Error(`[ReplayInit] Strict Mode Failure: The following cards were not found in the database: ${uniqueMissing.join(", ")}`);
    }

    return deck;
}

// ─────────────────────────────────────────────────────────────────────────────
// Initialization
// ─────────────────────────────────────────────────────────────────────────────

export interface ReplayInitOptions {
    seed: number;
    /** Which deck to use. Default: "standard" */
    deckId?: "standard" | "spell_heavy" | "empty";
    /** Starting PP for both players. Default: 1 */
    startingPP?: number;
    /** Cards to draw initially. Default: 3 */
    initialDraw?: number;
    /** If true, throws error on missing cards instead of logging warnings. Default: false */
    strict?: boolean;
}

/**
 * Initialize game state for replay testing.
 * This is a pure, headless initialization that doesn't require network or DOM.
 * 
 * IMPORTANT: The card database must be initialized before calling this function.
 * In Node.js, call initCardDatabaseNode() first.
 * 
 * @param targetState Optional state instance to initialize. Defaults to the singleton `state`.
 */
export function initReplayState(options: ReplayInitOptions, targetState?: GameState): GameState {
    const { seed, deckId = "standard", startingPP = 1, initialDraw = 3, strict = false } = options;
    const s = targetState || state;

    // Reset to clean state
    resetStateInstance(s, seed);

    // Set up PP
    s.bluePP = startingPP;
    s.blueMaxPP = startingPP;
    s.redPP = startingPP;
    s.redMaxPP = startingPP;

    if (deckId === "empty") {
        // Empty decks for minimal testing
        s.gameStarted = true;
        return s;
    }

    // Check if card database is initialized
    if (!isCardDatabaseInitialized()) {
        console.warn("[ReplayInit] Card database not initialized - using empty decks");
        s.gameStarted = true;
        return s;
    }

    // Get deck definition (standard is guaranteed to exist)
    const deckDef = REPLAY_DECKS[deckId] ?? REPLAY_DECK_STANDARD;

    // Build decks from card names
    const blueDeck = buildDeckFromNames(deckDef.cards, s.rng, strict);
    const redDeck = buildDeckFromNames(deckDef.cards, s.rng, strict);

    // Shuffle using seeded RNG - FIX: Shuffle returns a copy, we must use it!
    const blueShuffled = s.rng.shuffle(blueDeck);
    const redShuffled = s.rng.shuffle(redDeck);

    // Load decks
    s.blueDeck.push(...blueShuffled);
    s.redDeck.push(...redShuffled);

    if (initialDraw > 0) {
        // console.log(`[ReplayInit] BlueDeck Size: ${s.blueDeck.length}. Top 5: ${s.blueDeck.slice(0, 5).map(c => c.name).join(", ")}`);
    }

    // Draw initial hands
    for (let i = 0; i < initialDraw; i++) {
        drawCard(s.blueHand, s.blueDeck, "blue");
        drawCard(s.redHand, s.redDeck, "red");
    }

    s.gameStarted = true;
    s.isBlueTurn = true;

    return s;
}

/**
 * Helper to set PP for testing specific PP levels
 */
export function setPP(player: Player, current: number, max?: number): void {
    if (player === "blue") {
        state.bluePP = current;
        state.blueMaxPP = max ?? current;
    } else {
        state.redPP = current;
        state.redMaxPP = max ?? current;
    }
}

// src/logic/core/replayScenarioDsl.ts
// ─────────────────────────────────────────────────────────────────────────────
// REPLAY SCENARIO DSL - Selectors and action builders for UID-free scenarios
// ─────────────────────────────────────────────────────────────────────────────

import {
    GameState,
    CardInstance,
    Player,
    PlayCardAction,
    AttackAction,
    ChooseTargetAction,
    TargetSpec
} from "../../core/types.js";

// ─────────────────────────────────────────────────────────────────────────────
// Selector Options
// ─────────────────────────────────────────────────────────────────────────────

export interface CardSelector {
    /** Match by exact UID */
    uid?: string;
    /** Match by card name (exact or partial) */
    name?: string;
    /** Match by cost */
    cost?: number;
    /** Match by card type */
    cardType?: "Follower" | "Spell" | "Amulet";
    /** Match by index in the zone (0-based) */
    index?: number;
}

export interface BoardSelector extends CardSelector {
    owner: Player;
}

export interface TargetSelector {
    owner?: Player;
    zone: "board" | "leader";
    /** For board targets */
    index?: number;
    name?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Selectors
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Select a card from the player's hand.
 * Throws with descriptive error if not found.
 * 
 * Logic:
 * 1. If UID provided, match exactly.
 * 2. Filter hand by name/cost/type.
 * 3. If index is provided, select the N-th match from the candidates.
 * 4. If index is NOT provided, require exactly one match.
 */
export function selectCardInHand(
    state: GameState,
    owner: Player,
    selector: CardSelector
): CardInstance {
    const hand = owner === "blue" ? state.blueHand : state.redHand;

    // 0. UID Match (Fast path, exact)
    if (selector.uid) {
        const match = hand.find(c => c.uid === selector.uid);
        if (!match) {
            throw new Error(
                `selectCardInHand: No card found with UID ${selector.uid} for ${owner}.`
            );
        }
        return match;
    }

    // 1. Filter by Name/Cost/Type logic
    const candidates = hand.filter((card, i) => {
        if (selector.name !== undefined && !card.name.includes(selector.name)) return false;
        if (selector.cost !== undefined && Number(card.cost) !== selector.cost) return false;
        if (selector.cardType !== undefined && card.type !== selector.cardType) return false;
        return true;
    });

    if (candidates.length === 0) {
        const available = hand.map((c, i) => `[${i}] ${c.name} (${c.type}, cost ${c.cost})`).join(", ");
        throw new Error(
            `selectCardInHand: No card found matching criteria ${JSON.stringify(selector)} for ${owner}.\n` +
            `Available cards: ${available || "(empty hand)"}`
        );
    }

    // 2. Apply Index (Relative)
    if (selector.index !== undefined) {
        if (selector.index < 0 || selector.index >= candidates.length) {
            throw new Error(
                `selectCardInHand: Index ${selector.index} out of bounds for matches of ${JSON.stringify(selector)}.\n` +
                `Found ${candidates.length} matches.`
            );
        }
        return candidates[selector.index]!;
    }

    // 3. Single Match Requirement
    if (candidates.length > 1) {
        const matches = candidates.map(c => `${c.name} (${c.uid})`).join(", ");
        throw new Error(
            `selectCardInHand: Multiple cards match ${JSON.stringify(selector)} for ${owner}.\n` +
            `Matches: ${matches}\n` +
            `Specify 'index' to disambiguate (e.g. index: 0 for the first one).`
        );
    }

    return candidates[0]!;
}

/**
 * Select a follower/amulet on the board.
 * Throws with descriptive error if not found.
 * 
 * Logic: Same as selectCardInHand (Relative Indexing).
 */
export function selectFollowerOnBoard(
    state: GameState,
    selector: BoardSelector
): CardInstance {
    const board = selector.owner === "blue" ? state.blueBoard : state.redBoard;

    const candidates = board.filter((card) => {
        if (selector.name !== undefined && !card.name.includes(selector.name)) return false;
        if (selector.cost !== undefined && Number(card.cost) !== selector.cost) return false;
        if (selector.cardType !== undefined && card.type !== selector.cardType) return false;
        return true;
    });

    if (candidates.length === 0) {
        const available = board.map((c, i) => `[${i}] ${c.name} (${c.type}, cost ${c.cost})`).join(", ");
        throw new Error(
            `selectFollowerOnBoard: No card found matching ${JSON.stringify(selector)} for ${selector.owner}.\n` +
            `Available on board: ${available || "(empty board)"}`
        );
    }

    if (selector.index !== undefined) {
        if (selector.index < 0 || selector.index >= candidates.length) {
            throw new Error(
                `selectFollowerOnBoard: Index ${selector.index} out of bounds for matches of ${JSON.stringify(selector)}.\n` +
                `Found ${candidates.length} matches.`
            );
        }
        return candidates[selector.index]!;
    }

    if (candidates.length > 1) {
        const matches = candidates.map(c => `${c.name} (${c.uid})`).join(", ");
        throw new Error(
            `selectFollowerOnBoard: Multiple cards match ${JSON.stringify(selector)} for ${selector.owner}.\n` +
            `Matches: ${matches}\n` +
            `Specify 'index' to disambiguate.`
        );
    }

    return candidates[0]!;
}

/**
 * Select a target (board card or leader).
 * Returns a TargetSpec suitable for action payloads.
 */
export function selectTarget(
    state: GameState,
    selector: TargetSelector
): TargetSpec {
    if (selector.zone === "leader") {
        const player = selector.owner ?? "red"; // Default to enemy leader
        return { type: "leader", player };
    }

    // Board target
    const owner = selector.owner ?? "red";
    const boardSelector: BoardSelector = { owner };
    if (selector.index !== undefined) boardSelector.index = selector.index;
    if (selector.name !== undefined) boardSelector.name = selector.name;

    const card = selectFollowerOnBoard(state, boardSelector);
    return { type: "card", uid: card.uid };
}

// ─────────────────────────────────────────────────────────────────────────────
// Action Builders
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Build a PLAY_CARD action by selecting from hand.
 */
export function playCard(
    state: GameState,
    owner: Player,
    selector: CardSelector
): PlayCardAction {
    const card = selectCardInHand(state, owner, selector);
    return {
        type: "PLAY_CARD",
        player: owner,
        cardUid: card.uid
    };
}

/**
 * Build an ATTACK action.
 */
export function attackAction(
    state: GameState,
    attackerOwner: Player,
    attackerSelector: CardSelector,
    targetSelector: TargetSelector
): AttackAction {
    const attacker = selectFollowerOnBoard(state, { owner: attackerOwner, ...attackerSelector });
    const defender = selectTarget(state, targetSelector);

    return {
        type: "ATTACK",
        player: attackerOwner,
        attackerUid: attacker.uid,
        defender
    };
}

/**
 * Build a CHOOSE_TARGET action.
 */
export function chooseTarget(
    state: GameState,
    owner: Player,
    targetSelector: TargetSelector
): ChooseTargetAction {
    const target = selectTarget(state, targetSelector);
    return {
        type: "CHOOSE_TARGET",
        player: owner,
        target
    };
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper to list available cards (for debugging)
