import { GameState, CardInstance } from "../../../core/types.js";
import { TargetingResult, TargetedOpContext } from "./types.js";
import { validateTargetSelection } from "./validation.js";
import { toggleSelection } from "./selection.js";

/**
 * Core Targeting Engine.
 * Processes a click on a target (card or leader) and determines the next state.
 * Pure-ish: Mutates 'pending' state but has no side effects on game state otherwise.
 */
export function applyTargetClick(state: GameState, pending: any, uid: string | "leader"): TargetingResult {
    // 1. Handle Leader Targeting
    if (uid === "leader") {
        if (pending.canTargetLeader) {
            // Add special leader target
            pending.targets.push({ type: "Leader" });

            // Leader targeting is always immediate execution in current logic?
            // resolveTarget.ts: "Continue with normal resolution" -> runs effect.
            return {
                kind: "execute",
                opCtx: {
                    eff: pending.eff,
                    owner: pending.owner,
                    sourceCard: pending.sourceCard,
                    targets: pending.targets,
                    resumeEffects: pending.resumeEffects
                }
            };
        } else {
            return { kind: "invalid", reason: "Cannot target leader." };
        }
    }

    // 2. Resolve Card Entity
    // (We rely on state lookups here. Orchestrator passed us 'state'.)
    const all = [...state.blueBoard, ...state.redBoard, ...state.blueHand, ...state.redHand];
    const clickedTarget = all.find(c => c.uid === uid);

    if (!clickedTarget) {
        return { kind: "invalid", reason: `Target not found: ${uid}` };
    }

    // 3. Validation (Pool & Rules)
    const validation = validateTargetSelection(state, pending, uid);
    if (!validation.ok) {
        return { kind: "invalid", reason: validation.reason || "Invalid target" };
    }

    // 4. Special Case: Fortifier Fuse Finalization
    // (Clicking the source/initiator again confirms the selection)
    if (pending.eff?.op === "fuse_finalize_fortifier") {
        if (pending.sourceCard && uid === pending.sourceCard.uid) {
            if (pending.targets && pending.targets.length > 0) {
                return {
                    kind: "execute",
                    opCtx: {
                        eff: pending.eff,
                        owner: pending.owner,
                        sourceCard: pending.sourceCard,
                        targets: pending.targets,
                        resumeEffects: pending.resumeEffects
                    }
                };
            }
            // If targets empty, fall through to selection (toggle source?)
            // resolveTarget.ts would toggle source if it was in pool.
        }
    }

    // 5. Toggle Selection
    const outcome = toggleSelection(pending, clickedTarget);

    if (outcome === "removed") {
        // If unselected, and this caused confirmation to be hidden?
        // Engine just says "continue". Orchestrator handles UI updates.
        return { kind: "continue" };
    }

    // 6. Check Completion
    if (pending.requiresConfirmation) {
        // If we require confirmation, we enter "confirm_needed" state immediately after a valid selection?
        // resolveTarget.ts: "Show confirmation button... Wait for More Targets if Needed OR if we require manual confirmation"
        // line 336: "If we require confirmation, we stop here and wait for the button click"
        // So yes, we render and wait.
        return { kind: "confirm_needed" };
    }

    const requiredCount = (typeof pending.selectCount === "number" && Number.isFinite(pending.selectCount) && pending.selectCount > 0)
        ? pending.selectCount
        : 1;

    if (pending.targets.length < requiredCount) {
        return { kind: "continue" };
    }

    // 7. Complete & Auto-Execute
    return {
        kind: "execute",
        opCtx: {
            eff: pending.eff,
            owner: pending.owner,
            sourceCard: pending.sourceCard,
            targets: pending.targets,
            resumeEffects: pending.resumeEffects
        }
    };
}

// src/logic/core/targeting/validation.ts
import { GameState, Player, CardInstance } from "../../../core/types.js";

/** Result of a validation check */
export interface ValidationResult {
    ok: boolean;
    reason?: string;
}

/**
 * Validates if a specific target UID is a legal selection given the current pending state.
 * Checks:
 * 1. Target is in the allowed pool
 * 2. Lloyd enforcement (Global Taunt rules)
 */
export function validateTargetSelection(state: GameState, pending: any, uid: string): ValidationResult {
    // 1. Pool Validation
    const inPool = (pending.pool || []).some((p: any) => p.uid === uid);
    if (!inPool) {
        return { ok: false, reason: "Clicked card is not in the valid target pool." };
    }

    // 2. Lloyd Enforcement (Global Taunt)
    try {
        const me = pending.owner as Player;
        const opp: Player = me === "blue" ? "red" : "blue";
        const oppBoard = (opp === "blue" ? state.blueBoard : state.redBoard) || [];
        const lloyds = oppBoard.filter(c => c?.name === "Lloyd");

        if (lloyds.length > 0) {
            // Only care if the current pool includes opponent-side targets
            // We verify opponent-side status by board membership
            const poolHasOpponent = (pending.pool || []).some((c: any) =>
                (state.blueBoard?.includes(c) ? "blue" :
                    state.redBoard?.includes(c) ? "red" : null) === opp
            );

            if (poolHasOpponent) {
                const lloydUids = new Set(lloyds.map(l => l.uid));
                const firstPick = !pending.targets || pending.targets.length === 0;

                const safeCount = (typeof pending.selectCount === "number" && Number.isFinite(pending.selectCount) && pending.selectCount > 0)
                    ? pending.selectCount
                    : 1;

                const singlePick = safeCount <= 1;
                const clickedIsLloyd = lloydUids.has(uid);

                // Rule:
                // - Single-target: you can ONLY select (any) Lloyd.
                // - Multi-target: your FIRST pick must be (any) Lloyd. After that, anything valid is fine.
                if (singlePick && !clickedIsLloyd) {
                    return { ok: false, reason: "Lloyd: only Lloyd can be targeted." };
                }
                if (!singlePick && firstPick && !clickedIsLloyd) {
                    return { ok: false, reason: "Lloyd: you must select a Lloyd first." };
                }
            }
        }
    } catch (e) {
        // Fallback if state access fails, but don't block valid moves if logic errs
        // Return valid? Or fail safe? Original code warned and continued (implicit return undefined -> void -> ok?)
        // Original code logged warning and DID NOT return, so it allowed it implicitly.
        // We will return ok: true but log internal error? No, prompt said "No internal logging".
        // We will assume ok if exception occurs to avoid soft-lock.
        return { ok: true };
    }

    // All checks passed
    return { ok: true };
}

