/**
 * Handles the end of the blue player's turn and sets up the red player's turn.
 */
export function endTurnBlue() {
    console.error(`[Turns] endTurnBlue called. isBlueTurn: ${state.isBlueTurn}`);
    if (!state.isBlueTurn) return;
    recordEvent({ type: "end_turn", payload: { player: "blue" } });
    beginAction("End Turn (Blue)");

    clearTempHandCostMods("blue");
    state.blueBoard.forEach(card => clearTemporaryBuffs(card));
    fireTrigger("end_of_turn", "blue");
    // processHimekaDelayedBanish("blue");
    adapter.render();

    // Check End of Turn Invokes
    scanDeckForInvokes("blue", "end_of_turn");

    // ✅ Blue: run crest effects one by one, then cleanup once
    {
        const fx = processCrestEvent("blue", "end_of_turn");
        if (fx.length) {
            state.suppressCleanup = true;            // <— start atomic crest phase
            for (const eff of fx) {
                console.log("[Turns] Running crest effect op:", eff.op);
                runEffects([eff], "blue", null);
            }
            state.suppressCleanup = false;           // <— end atomic crest phase
        }
        cleanupDead();                             // resolve deaths + Last Words once
    }

    clearCantAttackUntilOpponentEOT(state.blueBoard);
    applyBleedAllBoardsAtEndOfTurn();

    state.redMaxPP = Math.min(state.roundCount + (state.redPermPP || 0), 10);
    state.redPP = state.redMaxPP;

    // Reset evolution usage flag
    state.blueEvoUsedThisTurn = false;

    clearSummoningSickness(state.redBoard);

    resetCrestOncePerTurn("red");
    resetEngageFlagsAtTurnStart("red");
    {
        const redStartFx = processCrestEvent("red", "start_of_turn");
        if (redStartFx.length) runEffects([...redStartFx], "red", null);
    }

    {
        const redCrestFx = tickCrests("red");
        if (redCrestFx.length) runEffects([...redCrestFx], "red", null);
    }
    cleanupDead();

    // Draw for Red
    drawCard(state.redHand, state.redDeck, "red");
    logEvent("draw", { player: "red", count: 1 });
    // Invoke Phase (Start of Turn)
    scanDeckForInvokes("red", "start_of_turn");

    state.redPlaysThisTurn = 0;

    refreshBoardForNewTurn(state.redBoard);

    state.isBlueTurn = false;

    tickAmuletCountdowns("red");
    cleanupDead();
    state.activePlayer = "red";
    logEvent("startTurn", { player: state.activePlayer, round: state.roundCount });
    state.redAnyAllyAttackedThisTurn = false;
    state.redEvoUsedThisTurn = false;
    resetShikigamiDeathLogs();

    adapter.render();
    logEvent("endTurn", { from: "blue" });
    commitAction({ autoRender: false });
}

export function endTurnRed() {
    if (state.isBlueTurn) return;
    beginAction("End Turn (Red)");

    clearTempHandCostMods("red");
    state.redBoard.forEach(card => clearTemporaryBuffs(card));
    fireTrigger("end_of_turn", "red");
    // processHimekaDelayedBanish("red");
    adapter.render();

    // Check End of Turn Invokes
    scanDeckForInvokes("red", "end_of_turn");

    // ✅ Red: run crest effects one by one, then cleanup once
    {
        const fx = processCrestEvent("red", "end_of_turn");
        if (fx.length) {
            state.suppressCleanup = true;
            for (const eff of fx) runEffects([eff], "red", null);
            state.suppressCleanup = false;
        }
        cleanupDead();
    }
    clearCantAttackUntilOpponentEOT(state.redBoard);
    applyBleedAllBoardsAtEndOfTurn();

    if (state.redBoostPending) {
        if (state.roundCount <= 5) state.redBoostUsedEarly = true;
        else state.redBoostUsedLate = true;
        state.redBoostPending = false;
    }

    state.roundCount++;

    state.blueMaxPP = Math.min(state.roundCount + (state.bluePermPP || 0), 10);
    state.bluePP = state.blueMaxPP;

    // Reset evolution usage flag
    state.redEvoUsedThisTurn = false;

    clearSummoningSickness(state.blueBoard);

    resetCrestOncePerTurn("blue");
    resetEngageFlagsAtTurnStart("blue");
    {
        const blueStartFx = processCrestEvent("blue", "start_of_turn");
        if (blueStartFx.length) runEffects([...blueStartFx], "blue", null);
    }

    {
        const blueCrestFx = tickCrests("blue");
        if (blueCrestFx.length) runEffects([...blueCrestFx], "blue", null);
    }
    cleanupDead();

    // Draw for Blue
    drawCard(state.blueHand, state.blueDeck, "blue");
    logEvent("draw", { player: "blue", count: 1 });
    // Invoke Phase (Start of Turn)
    scanDeckForInvokes("blue", "start_of_turn");

    state.bluePlaysThisTurn = 0;

    refreshBoardForNewTurn(state.blueBoard);

    state.isBlueTurn = true;
    tickAmuletCountdowns("blue");

    cleanupDead();
    state.activePlayer = "blue";
    logEvent("startTurn", { player: state.activePlayer, round: state.roundCount });
    state.blueAnyAllyAttackedThisTurn = false;
    state.blueEvoUsedThisTurn = false;
    resetShikigamiDeathLogs();

    adapter.render();
    logEvent("endTurn", { from: "red" });
    commitAction({ autoRender: false });
}


function handleCountdowns(owner: Player) {
    const board = owner === "blue" ? state.blueBoard : state.redBoard;
    board.forEach(card => {
        if (card?.type === "Amulet" && card.hasCountdown) {
            (card as any).countdown = (Number((card as any).countdown) || 0) - 1;
        }
    });
}

function clearSummoningSickness(board: CardInstance[]) {
    board.forEach(card => {
        if (card?.type === "Follower") {
            card.justPlayed = false;
        }
    });
}

function clearCantAttackUntilOpponentEOT(board: CardInstance[]) {
    board.forEach(card => {
        if (!card || card.type !== "Follower") return;
        if (!(card as any).cantAttackUntilOpponentEOT) return;

        // Drop all functional + UI flags
        delete (card as any).cantAttack;
        delete (card as any).cantAttackFollowers;
        delete (card as any).cantAttackLeaders;
        delete (card as any).cantAttackUntilOpponentEOT;
        delete (card as any).hasCantAttack;           // <-- fixes your CSS overlay never dropping

        // Make sure attackability is recalculated for UI/logic
        const perTurn = Number.isFinite((card as any).attacks_per_turn) ? (card as any).attacks_per_turn : 1;
        if ((card as any).attacks_left == null) (card as any).attacks_left = perTurn;
        // Respect rush/storm/summoning-sickness
        const eligible = (!!card.hasStorm) || (!card.justPlayed) || (!!card.hasRush);
        (card as any).can_attack = eligible && ((card as any).attacks_left > 0);
    });
}

function resetShikigamiDeathLogs() {
    state.shikigamiDeathsThisTurnBlue = [];
    state.shikigamiDeathsThisTurnRed = [];
}

import { state } from "../../core/gameState.js";
import { logEvent } from "../../core/logger.js";
import { Effect, Player, GameState } from "../../core/types.js";
import { fireTrigger } from "../core/triggers.js";

/**
 * Handles healing a leader's defense.
 * Now respects the dynamic maximum HP for each player.
 */
export function handleHealLeader(owner: Player, eff: Effect) {
    const amt = parseInt(eff.amount) || 0;

    const targetPlayerIsBlue =
        (eff.player || "self") === "self" ? owner === "blue" : owner !== "blue";

    logEvent("healLeader", { target: targetPlayerIsBlue ? "blue" : "red", amount: amt });

    // Apply healing, respecting the new dynamic max HP
    if (targetPlayerIsBlue) {
        state.blueHP = Math.max(0, Math.min(state.blueMaxHP, state.blueHP + amt));
    } else {
        state.redHP = Math.max(0, Math.min(state.redMaxHP, state.redHP + amt));
    }
}

/**
 * NEW: Sets a leader's maximum HP to a specific value.
 */
export function handleSetMaxHP(eff: Effect, owner: Player) {
    const targetPlayerString = eff.player || "self"; // 'self' or 'opponent'
    const amount = parseInt(eff.amount) || 20;

    const isOpponent = targetPlayerString === "opponent";
    const targetOwner: Player = isOpponent ? (owner === "blue" ? "red" : "blue") : owner;

    logEvent("setLeaderMaxHP", { owner: targetOwner, maxHP: amount });

    if (targetOwner === "blue") {
        state.blueMaxHP = amount;
        // Clamp current HP to the new max (no accidental +amt)
        state.blueHP = Math.max(0, Math.min(state.blueMaxHP, state.blueHP));
    } else {
        state.redMaxHP = amount;
        state.redHP = Math.max(0, Math.min(state.redMaxHP, state.redHP));
    }
}

/**
 * Handles recovering a player's play points for the current turn.
 * (This function is unchanged)
 */
export function handleRecoverPP(owner: Player, eff: Effect) {
    // Determine target side
    const targetIsBlue =
        (eff.player || "self") === "self" ? owner === "blue" : owner !== "blue";

    const cur = targetIsBlue ? state.bluePP : state.redPP;
    const max = targetIsBlue ? state.blueMaxPP : state.redMaxPP;

    // Allow symbolic "full" refills (your card uses "currentMaxPP")
    let amt;
    if (
        typeof eff.amount === "string" &&
        eff.amount.toLowerCase() === "currentmaxpp"
    ) {
        amt = Math.max(0, max - cur);
    } else {
        amt = parseInt(eff.amount) || 0;
    }

    const next = Math.min(max, cur + amt);
    if (targetIsBlue) state.bluePP = next;
    else state.redPP = next;
}

/**
 * (This function is unchanged but will now work correctly
 * because it calls the updated handleHealLeader)
 */
export function handleDynamicHealLeader(owner: Player, eff: Effect) {
    const hand = owner === "blue" ? state.blueHand : state.redHand;
    const amt = hand.length; // X is number of cards in hand
    handleHealLeader(owner, { ...eff, amount: amt });
}

/* ---------- NEW: leader barrier state ops ---------- */
export function grantLeaderBarrier(owner: Player, _charges = 1) {
    // Ignore extra charges: once the leader has Barrier, do nothing.
    const key = owner === "blue" ? "blueLeaderBarrier" : "redLeaderBarrier";
    if (state[key]) return; // already has Barrier

    const s = state as any; // Allow dynamic access for now or update GameState to have index signature
    s[key] = 1;
    logEvent("leaderBarrierGrant", { owner });
}

export function popLeaderBarrier(owner: Player, reason = "damage_prevent") {
    const key = owner === "blue" ? "blueLeaderBarrier" : "redLeaderBarrier";
    const s = state as any;
    if (!s[key]) return false;

    logEvent("leaderBarrierPop", { owner, reason });
    s[key] = 0;
    const fxKey =
        owner === "blue" ? "blueLeaderBarrierPopped" : "redLeaderBarrierPopped";
    s[fxKey] = reason;
    return true;
}

/** Centralized leader damage that respects barrier and max HP */
export function applyLeaderDamage(owner: Player, amount: number) {
    const hpKey = owner === "blue" ? "blueHP" : "redHP";
    // const maxKey = owner === "blue" ? "blueMaxHP" : "redMaxHP"; // Unused

    if ((amount | 0) <= 0) return 0;

    logEvent("leaderDamage", { owner, amount });

    // Barrier soaks the *whole packet* and consumes 1 charge
    if (popLeaderBarrier(owner, "leader_hit")) return 0;

    const s = state as any;
    const cur = s[hpKey] | 0;
    const next = Math.max(0, cur - (amount | 0));
    s[hpKey] = next;

    const actualDamage = cur - next;

    // Fire leader_damaged trigger AFTER damage is applied
    if (actualDamage > 0) {
        fireTrigger("leader_damaged", owner, {
            damagedLeader: owner,
            amount: actualDamage
        });
    }

    return actualDamage;
}

/* ---------- NEW: effect op for cards ---------- */
export function handleLeaderBarrierOp(owner: Player, eff: Effect) {
    const target: Player =
        (eff.player || "self") === "self"
            ? owner
            : owner === "blue"
                ? "red"
                : "blue";
    // Ignore eff.charges / eff.amount > 1
    grantLeaderBarrier(target, 1);
}
// NEW: Recover Evolution Points (capped at starting max)
export function handleRecoverEP(owner: Player, eff: Effect) {
    const amt = parseInt(eff.amount) || 0;
    const isBlue = (eff.player || "self") === "self" ? owner === "blue" : owner !== "blue";
    const MAX_EP = 2; // Starting maximum for both players
    if (isBlue) {
        state.blueEvoCharges = Math.min(MAX_EP, (state.blueEvoCharges || 0) + amt);
    } else {
        state.redEvoCharges = Math.min(MAX_EP, (state.redEvoCharges || 0) + amt);
    }
    logEvent("recoverEP", { owner: isBlue ? "blue" : "red", amount: amt });
}

import { state } from "../../../../core/gameState.js";
import { getPool, highlightSelectable } from "../../../core/targeting.js";
import { cleanupDead } from "../../../core/cleanup.js";
import { logEvent } from "../../../../core/logger.js";
import { CardInstance, Player } from "../../../../core/types.js";
import { BuffOp, BuffContext } from "./types.js";
import { filterBuffCandidates } from "./utils.js";
import { withBuffDuration } from "./duration.js";
import { applyStatBuff, applyKeywordBuff, applyAttacksPerTurnBuff, checkPostBuffTriggers } from "./core.js";
import { setPendingTarget } from "../../../core/pendingTarget/index.js";


export function handleBuffOrchestrator(
    eff: BuffOp,
    owner: Player,
    sourceCard: CardInstance | null,
    effectsQueue: any,
    context: any = {}
) {
    // 1. Get raw pool
    // pass context so targets like "entering_follower" work
    const rawPool = getPool(eff.target as any, owner, null, eff.condition, context);

    // 2. Filter candidates
    const pool = filterBuffCandidates(rawPool, eff, sourceCard);

    console.log('BUFF pool uids:', pool.map(c => c.uid), 'source:', sourceCard?.uid, 'include_self:', !!eff.include_self);

    if (!pool.length) return "done";

    // 3. Selection
    if ((eff as any).select) {
        setPendingTarget({
            eff,
            owner,
            sourceCard,
            resumeEffects: effectsQueue,
            pool,
            targets: [],
            selectCount: parseInt((eff as any).select_count ?? 1),
            context
        } as any);
        highlightSelectable(pool);
        return "pending";
    }

    // 4. Random Selection
    let chosen = pool;
    if (eff.random) {
        const k = Math.max(0, parseInt((eff.count as any) ?? 1, 10));
        if (k <= 0) return "done";

        chosen = [];
        const bag = [...pool];
        for (let i = 0; i < k && bag.length; i++) {
            const idx = state.rng.nextInt(bag.length);
            const picked = bag.splice(idx, 1)[0];
            if (picked) chosen.push(picked);
        }
        console.log("[Buff] Random chose:", chosen.map(c => c.uid));
    }

    // 5. Apply Buffs
    const mode = eff.random ? "random" : "all";

    for (const target of chosen) {
        // Use the duration wrapper for stats
        withBuffDuration(target, eff, ({ attack: a, defense: d }) => {
            applyStatBuff(target, a, d, owner);
            logEvent("buff", { owner, target: target.name, uid: target.uid, a, d, mode });

            // Post-buff triggers relate mainly to stats
            checkPostBuffTriggers(target, a, d, owner);
        });

        // Apply keywords
        applyKeywordBuff(target, eff);

        // Apply attacks per turn
        applyAttacksPerTurnBuff(target, eff, owner);
    }

    // 6. Cleanup
    cleanupDead();
    return "done";
}

