}

// Start fuse for Striker/Fortifier Artifact: "Fuse: Artifact cards"
export function startFortifierFuse(owner: Player, initiator: CardInstance) {
    const hand = handOf(owner);
    // pool = all *other* Artifact cards in hand
    const pool = hand.filter(c =>
        c?.uid !== initiator?.uid &&
        Array.isArray(c?.tribes) &&
        c.tribes.some(t => String(t).toLowerCase() === "artifact")
    );
    if (!pool.length) { clearSelectableFlags(); adapter.render(); return; }

    logEvent("fuseOpen", {
        owner,
        initiator: initiator.name,
        initiatorUid: initiator.uid,
        pool: pool.length,
        finalize: "fuse_finalize_fortifier"
    });

    setPendingTarget({
        eff: { op: "fuse_finalize_fortifier", initiator_uid: initiator.uid },
        owner,
        sourceCard: initiator,
        pool,
        selectCount: pool.length,            // select any number; confirm to finalize
        targets: [],
        resumeEffects: [],
        requiresConfirmation: true,
        confirmationText: "Fuse Selected Artifacts",
    });

    highlightSelectable(pool);
    adapter.render();
    return "pending";
}

export function startAlphaSelect(owner: Player, initiator: CardInstance) {
    const hand = handOf(owner);
    const pool = hand.filter(c =>
        c.uid !== initiator.uid &&
        (c.name === "Ominous Artifact β" || c.name === "Ominous Artifact γ")
    );
    if (!pool.length) return;

    logEvent("fuseOpen", {
        owner,
        initiator: initiator.name,
        initiatorUid: initiator.uid,
        pool: pool.length,
        finalize: "fuse_finalize_alpha"
    });

    setPendingTarget({
        eff: { op: "fuse_finalize_alpha", initiator_uid: initiator.uid },
        owner,
        sourceCard: initiator,
        pool,
        selectCount: Math.min(2, pool.length),
        targets: [],
        resumeEffects: [],
        requiresConfirmation: true,
        confirmationText: "Fuse Selected (β + γ → Ω)",
    });

    highlightSelectable(pool);
    adapter.render();
    return "pending";
}

// ---------- finalizers (export with op-string names) ----------
export function fuse_finalize_gear_multi(owner: Player, initiatorUid: string, partners: CardInstance[], resultName: string) {
    const hand = handOf(owner);
    const iIdx = hand.findIndex(c => c?.uid === initiatorUid);
    if (iIdx === -1) { clearSelectableFlags(); adapter.render(); return; }

    const initiator = hand[iIdx];
    if (!initiator) { clearSelectableFlags(); adapter.render(); return; }

    if (alreadyFusedThisTurn(initiator)) {
        logEvent("fuseBlocked", { owner, reason: "already_fused_this_turn", initiator: initiator?.name });
        clearSelectableFlags(); adapter.render(); return;
    }

    const tmpl = getCardDetails(resultName);
    if (!tmpl) { clearSelectableFlags(); adapter.render(); return; }

    const result = JSON.parse(JSON.stringify(tmpl));
    result.uid = state.rng.makeUid();

    hand[iIdx] = result;

    for (const p of partners || []) {
        const idx = hand.findIndex(c => c?.uid === p.uid);
        if (idx !== -1) hand.splice(idx, 1);
    }

    state.lastFuse = {
        owner,
        initiator_name: initiator?.name,
        partners_count: partners?.length || 0,
        result_name: resultName,
        targets: "merge"
    };

    try { fireTrigger("on_fuse", owner, { initiator, partners, result: { result_card_name: resultName } }); } catch { }

    logEvent("fuseFinalize", {
        owner,
        kind: "artifact",
        initiator: initiator?.name,
        partners: (partners || []).map(p => p.name),
        result: resultName,
    });

    clearSelectableFlags(); adapter.render();
}

export function fuse_finalize_fortifier(owner: Player, initiatorUid: string, partners: CardInstance[]) {
    const hand = handOf(owner);
    const iIdx = hand.findIndex(c => c?.uid === initiatorUid);
    if (iIdx === -1) { clearSelectableFlags(); adapter.render(); return; }

    const initiator = hand[iIdx];
    if (!initiator) { clearSelectableFlags(); adapter.render(); return; }

    if (alreadyFusedThisTurn(initiator)) {
        logEvent("fuseBlocked", { owner, reason: "already_fused_this_turn", initiator: initiator?.name });
        clearSelectableFlags(); adapter.render(); return;
    }

    const sumCost = (partners || []).reduce((acc: number, p: CardInstance) => {
        const eff = Number.isFinite(p?.effectiveCost) ? p.effectiveCost! :
            (Number(p?.cost) || 0) + (Number(p?.cost_mod) || 0);
        return acc + eff;
    }, 0);

    const resultName =
        sumCost === 1 as any ? "Ominous Artifact α" :
            sumCost === 2 ? "Ominous Artifact β" :
                "Ominous Artifact γ";

    const tmpl = getCardDetails(resultName);
    if (!tmpl) { clearSelectableFlags(); adapter.render(); return; }

    const newCard = JSON.parse(JSON.stringify(tmpl));
    newCard.uid = state.rng.makeUid();

    hand[iIdx] = newCard;
    for (const p of partners || []) {
        const idx = hand.findIndex(c => c?.uid === p.uid);
        if (idx !== -1) hand.splice(idx, 1);
    }

    state.lastFuse = { owner, initiator_name: initiator.name, totalCost: sumCost, result_name: resultName };
    try { fireTrigger("on_fuse", owner, { initiator, partners, result: { result_card_name: resultName } }); } catch { }

    logEvent("fuseFinalize", {
        owner,
        kind: "artifact",
        initiator: initiator?.name,
        partners: (partners || []).map(p => p.name),
        result: resultName,
    });

    clearSelectableFlags(); adapter.render();
}

export function fuse_finalize_alpha(owner: Player, initiatorUid: string, partners: CardInstance[]) {
    const hand = handOf(owner);
    const iIdx = hand.findIndex(c => c?.uid === initiatorUid);
    if (iIdx === -1) { clearSelectableFlags(); adapter.render(); return; }

    const initiator = hand[iIdx];
    if (!initiator) { clearSelectableFlags(); adapter.render(); return; }

    if (alreadyFusedThisTurn(initiator)) {
        logEvent("fuseBlocked", { owner, reason: "already_fused_this_turn", initiator: initiator?.name });
        clearSelectableFlags(); adapter.render(); return;
    }

    const names = (partners || []).map(p => p?.name);
    const hasBeta = names.includes("Ominous Artifact β");
    const hasGamma = names.includes("Ominous Artifact γ");

    const idxOf = (uid: string) => hand.findIndex(c => c?.uid === uid);

    if (hasBeta && hasGamma) {
        const tmpl = getCardDetails("Masterwork Artifact Ω");
        if (!tmpl) { clearSelectableFlags(); adapter.render(); return; }
        const omega = JSON.parse(JSON.stringify(tmpl));
        omega.uid = state.rng.makeUid();

        hand[iIdx] = omega;

        const partnerIdxsDesc = (partners || [])
            .map(p => idxOf(p?.uid))
            .filter(ix => ix !== -1 && ix !== iIdx)
            .sort((a, b) => b - a);

        for (const ix of partnerIdxsDesc) hand.splice(ix, 1);

        state.lastFuse = {
            owner,
            initiator_name: "Ominous Artifact α",
            partners_count: partners.length,
            result_name: "Masterwork Artifact Ω",
            targets: "merge"
        };
    } else if ((partners || []).length === 1 as any) {
        const partner0 = partners[0];
        if (!partner0) { clearSelectableFlags(); adapter.render(); return; }
        const pIdx = idxOf(partner0.uid);
        if (pIdx !== -1) hand.splice(pIdx, 1);
        state.lastFuse = {
            owner,
            initiator_name: "Ominous Artifact α",
            partner_name: partners[0]?.name,
            result_name: "wasted"
        };

        logEvent("fuseFinalize", {
            owner,
            kind: "artifact_alpha",
            initiator: "Ominous Artifact α",
            partners: (partners || []).map(p => p.name),
            result: "wasted",
        });
    }

    try {
        fireTrigger("on_fuse", owner, {
            initiator,
            partners,
            result: { result_card_name: hasBeta && hasGamma ? "Masterwork Artifact Ω" : "wasted" }
        });
    } catch { /* no-op */ }

    if (hand[iIdx]?.name === "Ominous Artifact α") {
        hand[iIdx].lastFuseRound = state.roundCount;
    }

    if (hasBeta && hasGamma) {
        logEvent("fuseFinalize", {
            owner,
            kind: "artifact_alpha",
            initiator: "Ominous Artifact α",
            partners: (partners || []).map(p => p.name),
            result: "Masterwork Artifact Ω",
        });
    }

    clearSelectableFlags(); adapter.render();
}

// src/logic/effects/ops/fuse/fuse.ts
import { state } from "../../../../core/gameState.js";
import { adapter } from "../../../../core/adapter.js";
import { highlightSelectable, clearSelectableFlags } from "../../../core/targeting.js";
import { fireTrigger } from "../../../core/triggers.js";
import { getCardDetails } from "../../../../data/cardDatabase.js";
import { setPendingTarget } from "../../../core/pendingTarget/index.js";

import { logEvent } from "../../../../core/logger.js";
import { CardInstance, GameState, Player } from "../../../../core/types.js";

// Class-specific modules
import {
    startGearMultiSelect,
    startAlphaSelect,
    startFortifierFuse,
    fuse_finalize_alpha,
    fuse_finalize_gear_multi,
    fuse_finalize_fortifier,
} from "./fuse.artifact.js";

import {
    fuse_finalize_gardens_allure,
} from "./fuse.forest.js";

import {
    fuse_finalize_loot,
} from "./fuse.loot.js";

// Re-export finalize handlers so runEffects can find them by op string
export {
    fuse_finalize_alpha,
    fuse_finalize_gear_multi,
    fuse_finalize_fortifier,
    fuse_finalize_gardens_allure,
    fuse_finalize_loot,
    startFortifierFuse,
};

// -------------------- shared helpers --------------------
function handOf(owner: Player) {
    return owner === "blue" ? state.blueHand : state.redHand;
}

function alreadyFusedThisTurn(card: CardInstance | null) {
    return !!card && card.lastFuseRound === state.roundCount;
}

function filterByPartnerFilters(candidates: CardInstance[], filters: any[] = []) {
    if (!Array.isArray(filters) || filters.length === 0) return candidates;

    const pass = (card: CardInstance, f: any) => {
        if (f.zone && f.zone !== "hand") return false;

        const cType = String(card?.type || "").toLowerCase();
        const cClass = String(card?.class || "").toLowerCase();
        const wantType = String(f.type ?? f.type_eq ?? "").toLowerCase();
        const wantClass = String(f.class ?? f.class_eq ?? "").toLowerCase();

        if (wantType && cType !== wantType) return false;
        if (wantClass && cClass !== wantClass) return false;

        if (Array.isArray(f.name_in) && !f.name_in.includes(card.name)) return false;
        if (f.tribe && !(Array.isArray(card.tribes) && card.tribes.includes(f.tribe))) return false;

        if (Number.isFinite(f.cost_max)) {
            const effCost = (Number(card?.effectiveCost) ?? Number(card?.cost) ?? 0) + (Number(card?.cost_mod) || 0);
            if (effCost > f.cost_max) return false;
        }
        if (f.keyword) {
            const kws = Array.isArray(card?.keywords) ? card.keywords : [];
            const hasKw = kws.some(k => (typeof k === "string" ? k : k?.name) === f.keyword);
            if (!hasKw) return false;
        }
        return true;
    };

    return candidates.filter(c => filters.some(f => pass(c, f)));
}

function buildPartnerPool(owner: Player, initiator: CardInstance) {
    const hand = handOf(owner);
    const recipes = initiator?.fuse_recipes;
    if (!Array.isArray(recipes) || recipes.length === 0) return null;

    for (let rIndex = 0; rIndex < recipes.length; rIndex++) {
        const r = recipes[rIndex];
        const pool = filterByPartnerFilters(
            hand.filter(c => c?.uid !== initiator.uid),
            r.partner_filters
        );
        if (pool.length) return { recipe: r, recipeIndex: rIndex, pool };
    }
    return null;
}

// -------------------- central starter --------------------
export function opStartFuseFromCard(eff: any, owner: Player) {
    const hand = handOf(owner);
    const initiatorUid = eff?.initiator_uid;
    if (!initiatorUid) return;

    const initiator = hand.find(c => c?.uid === initiatorUid);
    if (!initiator) return;

    if (alreadyFusedThisTurn(initiator)) {
        console.warn("[Fuse] This copy already fused this turn.");
        logEvent("fuseBlocked", { owner, reason: "already_fused_this_turn", initiator: initiator?.name });
        clearSelectableFlags();
        adapter.render();
        return "done";
    }

    // --- Portalcraft special cases ---
    if (initiator?.name === "Gear of Ambition" || initiator?.name === "Gear of Remembrance") {
        return startGearMultiSelect(owner, initiator);
    }
    if (initiator?.name === "Ominous Artifact α") {
        return startAlphaSelect(owner, initiator);
    }

    // --- Generic single/multi partner path (honors recipe.finalize_op) ---
    const info = buildPartnerPool(owner, initiator);
    if (!info) return;

    // If recipe provides a custom finalize op, use a confirmable multi-select
    if (info.recipe?.finalize_op) {
        setPendingTarget({
            eff: { op: info.recipe.finalize_op, initiator_uid: initiator.uid },
            owner,
            sourceCard: initiator,
            pool: info.pool,
            selectCount: info.pool.length,
            targets: [],
            resumeEffects: [],
            requiresConfirmation: true,
            confirmationText: "Fuse Selected Cards",
        });
        logEvent("fuseOpen", {
            owner,
            initiator: initiator.name,
            initiatorUid: initiator.uid,
            recipe: info?.recipe?.id || null,
            pool: info?.pool?.length || 0,
            finalize: info?.recipe?.finalize_op || "fuse_finalize_generic"
        });
        highlightSelectable(info.pool);
        adapter.render();
        return "pending";
    }

    // Otherwise fall back to generic transform/waste (kept for backward compatibility)
    setPendingTarget({
        eff: {
            op: "fuse_finalize_generic",
            initiator_uid: initiator.uid,
            recipe_id: info.recipe?.id || null,
            recipe_index: info.recipeIndex,
            result: info.recipe?.result || null
        },
        owner,
        sourceCard: initiator,
        pool: info.pool,
        selectCount: 1,
        targets: [],
        resumeEffects: [],
    });

    logEvent("fuseOpen", {
        owner,
        initiator: initiator.name,
        initiatorUid: initiator.uid,
        recipe: info?.recipe?.id || null,
        pool: info?.pool?.length || 0,
        finalize: info?.recipe?.finalize_op || "fuse_finalize_generic"
    });
    highlightSelectable(info.pool);
    adapter.render();
    return "pending";
}

// -------------------- generic finalize (unchanged behavior) --------------------
export function fuse_finalize_generic(owner: Player, initiatorUid: string, partnerCard: CardInstance, resultSpec: any) {
    const hand = handOf(owner);

    const iIdx = hand.findIndex(c => c?.uid === initiatorUid);
    const pIdx = hand.findIndex(c => c?.uid === partnerCard?.uid);
    if (iIdx === -1 || pIdx === -1) { clearSelectableFlags(); adapter.render(); return; }

    const iCard = hand[iIdx];
    const pCard = hand[pIdx];
    if (!iCard || !pCard) { clearSelectableFlags(); adapter.render(); return; }

    if (resultSpec?.type === "waste") {
        if (resultSpec.consume === "partner") {
            hand.splice(pIdx, 1);
        } else if (resultSpec.consume === "initiator") {
            hand.splice(iIdx, 1);
        }
        state.lastFuse = {
            owner,
            time: Date.now(),
            initiator_name: iCard?.name,
            partner_name: pCard?.name,
            result_name: "wasted"
        };
        clearSelectableFlags(); adapter.render(); return;
    }

    if (!resultSpec || resultSpec.type !== "transform") {
        clearSelectableFlags(); adapter.render(); return;
    }

    const tmpl = getCardDetails(resultSpec.result_card_name);
    if (!tmpl) { clearSelectableFlags(); adapter.render(); return; }

    const mk = () => {
        const c = JSON.parse(JSON.stringify(tmpl));
        c.uid = state.rng.makeUid();
        return c;
    };

    const targets = String(resultSpec.targets || "merge").toLowerCase();

    if (targets === "merge") {
        const min = Math.min(iIdx, pIdx);
        const max = Math.max(iIdx, pIdx);
        hand[min] = mk();
        hand.splice(max, 1);
    } else if (targets === "initiator") {
        hand[iIdx] = mk();
    } else if (targets === "partner") {
        hand[pIdx] = mk();
    } else {
        const min = Math.min(iIdx, pIdx);
        const max = Math.max(iIdx, pIdx);
        hand[min] = mk();
        hand.splice(max, 1);
    }

    // collapse accidental duplicates of same name next to each other
    const name = resultSpec.result_card_name;
    for (let k = hand.length - 2; k >= 0; k--) {
        if (hand[k]?.name === name && hand[k + 1]?.name === name) {
            hand.splice(k + 1, 1);
            break;
        }
    }

    state.lastFuse = {
        owner,
        time: Date.now(),
        initiator_name: iCard?.name,
        partner_name: pCard?.name,
        result_name: resultSpec.result_card_name,
        targets: "merge"
    };

    try { fireTrigger?.("on_fuse", owner, { initiator: iCard, partner: pCard, result: resultSpec }); } catch { }

    logEvent("fuseFinalize", {
        owner,
        kind: "generic",
        initiator: iCard?.name,
        partner: pCard?.name,
        result: resultSpec?.result_card_name || state?.lastFuse?.result_name || "wasted",
        targets
    });
    clearSelectableFlags(); adapter.render();
}

// src/logic/effects/ops/misc.ts

import { state } from "../../../core/gameState.js";
import { adapter } from "../../../core/adapter.js";
import { handleDamageAll, handleDamageRandom } from "./damage.js";
import { destroyAlliedAmulets } from "./destroy.js";
import { applyLeaderDamage, handleHealLeader } from "../leader.js";
import { Player, CardInstance, Effect } from "../../../core/types.js";
import { addMaxPP } from "../../pp.js";

// destroy_allied_amulets_then_damage
export function handleDestroyAlliedAmuletsThenDamage(owner: Player) {
    const x = destroyAlliedAmulets(owner) | 0;
    if (x > 0) {
        handleDamageAll({ op: "damage_all", target: "enemy:follower", amount: x } as any, owner);
        handleDamageAll({ op: "damage_all", target: "enemy:leader", amount: x } as any, owner);
    }
}

// damage_enemy_leader_by_other_allies
export function handleDamageEnemyLeaderByOtherAllies(owner: Player, sourceCard: CardInstance) {
    const myBoard = owner === "blue" ? state.blueBoard : state.redBoard;
    const x = (myBoard || []).filter(c => c && (!sourceCard || c.uid !== sourceCard.uid)).length | 0;
    const enemy = owner === "blue" ? "red" : "blue";
    if (x > 0) applyLeaderDamage(enemy, x);
}

// destroy_random_other_allies
export function handleDestroyRandomOtherAllies(owner: Player, sourceCard: CardInstance, context: any) {
    const board = owner === "blue" ? state.blueBoard : state.redBoard;
    const x = (board || []).filter(c => c && (!sourceCard || c.uid !== sourceCard.uid)).length | 0;
    for (let i = 0; i < x; i++) {
        handleDamageRandom(
            { op: "destroy_random", target: "enemy:follower", count: 1 } as any,
            owner
            // Note: original code called handleDestroyRandom but op was "destroy_random".
        );
    }
}

// restore_full_defense_self
export function handleRestoreFullDefenseSelf(sourceCard: CardInstance, context: any) {
    if (sourceCard && sourceCard.type === "Follower") {
        const curr = parseInt(String(sourceCard.defense), 10) || 0;
        const full =
            Number.isFinite(sourceCard.potential_defense) ? sourceCard.potential_defense! :
                Number.isFinite(sourceCard.peak_defense) ? sourceCard.peak_defense! :
                    Number.isFinite(sourceCard.base_defense) ? sourceCard.base_defense! :
                        curr;

        const restored = Math.max(0, (full as number) - curr);
        sourceCard.defense = full;

        // make available to chained effects in this sequence
        sourceCard.__lastRestored = restored;
        if (context) context.__restored_amount = restored;
    }
}

// restore_self_and_heal_leader
export function handleRestoreSelfAndHealLeader(owner: Player, sourceCard: CardInstance) {
    if (sourceCard?.type !== "Follower") return;

    const curr = parseInt(String(sourceCard.defense), 10) || 0;
    const full =
        Number.isFinite(sourceCard.potential_defense) ? sourceCard.potential_defense! :
            Number.isFinite(sourceCard.peak_defense) ? sourceCard.peak_defense! :
                Number.isFinite(sourceCard.base_defense) ? sourceCard.base_defense! :
                    curr;

    const restored = Math.max(0, (full as number) - curr);
    if (restored > 0) {
        sourceCard.defense = full;
        handleHealLeader(owner, { amount: restored } as any);
    }
    adapter.render();
}

// --- Logic Moved from effects.ts ---

export function handleChooseBonusAdd(owner: Player, eff: Effect) {
    const amt = (eff.amount || 1) as number;
    if (owner === "blue") state.blueChooseBonus = (state.blueChooseBonus || 0) + amt;
    else state.redChooseBonus = (state.redChooseBonus || 0) + amt;
}

export function handleGainMaxPP(owner: Player, eff: Effect) {
    const amt = (eff.amount || 1) as number;
    addMaxPP(owner, amt, { cap: 10, recalcNow: true });
}

export function handleSetCostLastDrawn(eff: Effect) {
    const v = parseInt((eff.amount as string) || "0");
    if (!Number.isFinite(v)) return;
    const arr = state.lastDrawnCards || [];
    const target = arr[0]; // most recently drawn
    if (target) {
        if (target.base_cost === undefined) {
            target.base_cost = parseInt(String(target.cost)) || 0;
        }
        target.cost = Math.max(0, v);
    }
}

export function handleRestoreAllies(owner: Player, eff: Effect) {
    console.log(`[Op] Restore Allies for ${owner}`);
    const amount = (eff.amount || 1) as number;

    // 1. Heal Leader
    handleHealLeader(owner, { amount } as any);

    // 2. Heal Followers
    const board = owner === "blue" ? state.blueBoard : state.redBoard;
    for (const c of board) {
        if (!c || c.type !== "Follower") continue;
        const curr = parseInt(String(c.defense), 10) || 0;
        const full =
            Number.isFinite(c.potential_defense) ? c.potential_defense! :
                Number.isFinite(c.peak_defense) ? c.peak_defense! :
                    Number.isFinite(c.base_defense) ? c.base_defense! :
                        curr;

        // Can only restore up to the difference
        const canRestore = (full as number) - curr;
        if (canRestore > 0) {
            const actual = Math.min(amount, canRestore);
            c.defense = curr + actual;
            // No specific trigger fired per follower here for simplicity, 
            // but in a full engine we'd fire 'on_heal' per unit.
        }
    }
}

// src/logic/effects/ops/reanimate.ts
import { state } from "../../../core/gameState.js";
import { getCardDetails } from "../../../data/cardDatabase.js";
import { reanimateSummon } from "./summon.js";

import { logEvent } from "../../../core/logger.js";
import { Effect, Player, CardInstance } from "../../../core/types.js";



export function handleReanimate(eff: Effect, owner: Player) {
    const maxCost = parseInt(String((eff as any).max_cost ?? (eff as any).cost ?? (eff as any).x ?? 0)) || 0;
    const grave = owner === "blue" ? state.blueGraveyard : state.redGraveyard;

    // Find all followers in graveyard with cost <= maxCost
    const eligible = grave.filter(card =>
        card.type === "Follower" &&
        (parseInt((card as any).cost) || 0) <= maxCost
    );

    if (eligible.length === 0) {
        console.log(`No eligible followers to reanimate (maxCost=${maxCost}). Grave size: ${grave.length}`);
        // console.log("Grave dump:", grave.map(c => `${c.name} (${c.cost})`));
        return;
    }

    // Group by cost for prioritization
    const byCost: Record<number, CardInstance[]> = {};
    eligible.forEach(card => {
        const cost = parseInt((card as any).cost) || 0;
        byCost[cost] = byCost[cost] || [];
        byCost[cost].push(card);
    });

    // Try to find highest cost available (up to maxCost)
    let candidates: CardInstance[] = [];
    for (let cost = maxCost; cost >= 0; cost--) {
        const costCandidates = byCost[cost];
        if (costCandidates && costCandidates.length > 0) {
            candidates = costCandidates;
            break;
        }
    }

    if (candidates.length === 0) {
        console.log("No candidates found despite eligibility check");
        return;
    }

    // Randomly select one from the highest available cost group
