import path from "path";
import fs from "fs";

const project = new Project({
    tsConfigFilePath: "tsconfig.json",
});

const FORBIDDEN_LAYER = "/src/ui";
const GUARDED_LAYERS = ["/src/core", "/src/logic"];

let violations = 0;

console.log("🛡️  Checking Architecture Boundaries...");
try { fs.unlinkSync("boundary_errors.txt"); } catch (e) { }

const sourceFiles = project.getSourceFiles();

for (const sourceFile of sourceFiles) {
    const filePath = sourceFile.getFilePath();

    // Check if this file is in a guarded layer
    const guarded = GUARDED_LAYERS.find(layer => filePath.includes(layer));
    if (!guarded) continue;

    const imports = sourceFile.getImportDeclarations();
    const exports = sourceFile.getExportDeclarations();
    const dynamicImports = sourceFile.getDescendantsOfKind(210); // SyntaxKind.CallExpression, need to check for import()

    // Helper to check specifier
    const checkSpecifier = (specifier, nodeType, lineNum) => {
        if (!specifier) return;

        // Resolve path roughly or use TS module resolution if needed.
        // ts-morph sourceFile.getReferencedSourceFiles() is easiest but doesn't show *which* import caused it easily.
        // We'll trust specifier string manipulation for strictness or use resolution.

        // Better: let ts-morph resolve it.
        let resolvedFile;
        try {
            // This works for static imports/exports
            if (nodeType === "import" || nodeType === "export") {
                const declaration = nodeType === "import"
                    ? sourceFile.getImportDeclaration(d => d.getModuleSpecifierValue() === specifier)
                    : sourceFile.getExportDeclaration(d => d.getModuleSpecifierValue() === specifier);

                if (declaration) {
                    const sf = declaration.getModuleSpecifierSourceFile();
                    if (sf) resolvedFile = sf.getFilePath();
                }
            }
        } catch (e) { }

        // Fallback: manual resolution if ts-morph didn't find it (non-ts file?) or just simple check
        if (!resolvedFile) {
            if (specifier.startsWith(".")) {
                resolvedFile = path.resolve(path.dirname(filePath), specifier);
            }
        }

        if (resolvedFile && resolvedFile.toLowerCase().replace(/\\/g, "/").includes(FORBIDDEN_LAYER)) {
            const msg = `❌ [VIOLATION] ${path.relative(process.cwd(), filePath)}:${lineNum}\n   Imports UI layer: '${specifier}' -> ${resolvedFile}\n`;
            console.error(msg);
            fs.appendFileSync("boundary_errors.txt", msg);
            violations++;
        }
    };

    // 1. Static Imports
    for (const decl of imports) {
        checkSpecifier(decl.getModuleSpecifierValue(), "import", decl.getStartLineNumber());
    }

    // 2. Static Exports
    for (const decl of exports) {
        if (decl.hasModuleSpecifier()) {
            checkSpecifier(decl.getModuleSpecifierValue(), "export", decl.getStartLineNumber());
        }
    }

    // 3. Dynamic Imports (manual AST walk for ImportKeyword usually)
    // ts-morph simplifies this: sourceFile.getImportStringLiterals() gives all?
    // Let's stick to simple CallExpression check for import('...')
    // actually imports are usually distinct.

    const callExpressions = sourceFile.getDescendants().filter(n => {
        // SyntaxKind.CallExpression = 213 (in newer TS) or similar. 
        // Safer to check input form.
        return n.getKindName() === "CallExpression" && n.getExpression().getKindName() === "ImportKeyword";
    });

    for (const call of callExpressions) {
        const args = call.getArguments();
        if (args.length > 0 && args[0].getKindName() === "StringLiteral") {
            const specifier = args[0].getLiteralText();
            checkSpecifier(specifier, "dynamic", call.getStartLineNumber());
        }
    }
}

if (violations > 0) {
    console.error(`\n🚨 Found ${violations} architecture violations.`);
    console.error("   Core/Logic modules MUST NOT import from UI.");
    process.exit(1);
} else {
    console.log("✅ Boundaries respected.");
    process.exit(0);
}

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { compileCardText } from '../src/data/textCompiler/compiler.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const ROOT = path.resolve(__dirname, '../');
const RAW_DIR = path.join(ROOT, 'cards/raw');
const COMPILED_DIR = path.join(ROOT, 'cards/compiled');

if (!fs.existsSync(COMPILED_DIR)) {
    fs.mkdirSync(COMPILED_DIR, { recursive: true });
}

async function main() {
    console.log(`Searching for raw cards in ${RAW_DIR}...`);
    if (!fs.existsSync(RAW_DIR)) {
        console.error("Raw directory not found.");
        process.exit(1);
    }

    const files = fs.readdirSync(RAW_DIR).filter(f => f.endsWith('.json'));

    for (const file of files) {
        console.log(`Processing ${file}...`);
        const rawContent = fs.readFileSync(path.join(RAW_DIR, file), 'utf-8');
        let cards;
        try {
            cards = JSON.parse(rawContent);
            if (!Array.isArray(cards)) cards = [cards];
        } catch (e) {
            console.error(`Failed to parse ${file}:`, e);
            continue;
        }

        const compiledCards = cards.map((raw: any) => {
            console.log(`  Compiling ${raw.name}...`);
            const compiled = compileCardText(raw.text || "", raw.type || "Follower");

            // Merge compiled effects with raw structure
            return {
                id: raw.id,
                name: raw.name,
                type: raw.type,
                class: raw.craft || raw.class, // normalize
                cost: raw.cost,
                stats: raw.stats, // optional
                // Compiler outputs
                keywords: compiled.keywords,
                fanfare: compiled.fanfare,
                lastWordsEffects: compiled.lastWords,
                spell: compiled.spell,
                unresolved: compiled.unresolved,
                // Debug info
                sourceText: raw.text
            };
        });

        const outFile = path.join(COMPILED_DIR, file); // matched filename
        fs.writeFileSync(outFile, JSON.stringify(compiledCards, null, 2));
        console.log(`  Wrote ${compiledCards.length} cards to ${outFile}`);
    }
}

main().catch(e => console.error(e));

const { Project, SyntaxKind } = require("ts-morph");
const path = require("path");
const fs = require("fs");

async function main() {
    console.log("Initializing project from tsconfig.json...");
    // Initialize project based on tsconfig.json
    const project = new Project({
        tsConfigFilePath: "tsconfig.json",
        skipAddingFilesFromTsConfig: false,
    });
    project.addSourceFilesAtPaths("tests/**/*.ts");

    const sourceFiles = project.getSourceFiles();
    console.log(`Files found in project: ${sourceFiles.length}`);

    let modifications = 0;

    // Helper to determine if a specifier is an alias we want to rewrite
    const aliases = ["@core", "@data", "@logic", "@ui", "@helpers", "@ops", "#core", "#logic", "#ui", "#helpers", "#data"];

    function isAliased(specifier) {
        return aliases.some(a => specifier.startsWith(a));
    }

    // Helper: Determine if we should attempt to resolve this specifier
    function shouldRewrite(specifier) {
        return isAliased(specifier);
    }

    for (const sourceFile of sourceFiles) {
        const filePath = sourceFile.getFilePath();

        // Skip dist and node_modules explicitly
        if (filePath.includes("/dist/") || filePath.includes("/node_modules/")) continue;

        // console.log(`Processing ${path.relative(process.cwd(), filePath)}...`);

        // Helper import rewriter
        const rewrite = (specifier, nodeToWarn) => {
            if (!shouldRewrite(specifier)) return null;

            // Try to resolve
            const resolvedSourceFile = nodeToWarn.getModuleSpecifierSourceFile();

            if (resolvedSourceFile) {
                const resolvedPath = resolvedSourceFile.getFilePath();

                let relativePath = path.relative(path.dirname(filePath), resolvedPath);

                // Normalize separators
                relativePath = relativePath.split(path.sep).join("/");

                if (!relativePath.startsWith(".")) {
                    relativePath = "./" + relativePath;
                }

                // Remove extension
                // Logic: strict removal of .ts, .tsx, .d.ts, .js
                // We want extensionless imports for TS source files
                const ext = path.extname(relativePath);
                // remove extension if present
                if (ext === '.ts' || ext === '.tsx' || ext === '.js' || ext === '.jsx') {
                    relativePath = relativePath.substring(0, relativePath.length - ext.length);
                }
                else if (relativePath.endsWith(".d.ts")) {
                    relativePath = relativePath.substring(0, relativePath.length - 5);
                }

                // Handle index
                if (relativePath.endsWith("/index")) {
                    relativePath = relativePath.substring(0, relativePath.length - 6);
                    if (relativePath === "") relativePath = ".";
                }

                if (specifier === relativePath) return null; // No change

                // console.log(`  Rewrite: ${specifier} -> ${relativePath}`);
                return relativePath;

            } else {
                // Fallback for # imports if they point to .js files in dist?
                // Since tsconfig maps @core etc., but not #core unless we add it to paths?
                // But user has #core mapped to ./dist/core/*.js in package.json
                // ts-morph reading tsconfig might NOT resolve #core if it's not in paths.
                // We need to handle this manually if getModuleSpecifierSourceFile fails.

                // Manual fallback for # aliases
                if (specifier.startsWith("#")) {
                    // Map #core/foo -> src/core/foo
                    // Helper map based on user info
                    const manualMap = {
                        "#core": "src/core",
                        "#logic": "src/logic",
                        "#ui": "src/ui",
                        "#helpers": "src/helpers",
                        "#data": "src/data"
                    };

                    for (const [alias, targetDir] of Object.entries(manualMap)) {
                        if (specifier.startsWith(alias)) {
                            const rest = specifier.substring(alias.length);
                            // construct absolute path
                            // removing leading slash if any
                            const cleanRest = rest.startsWith("/") ? rest.substring(1) : rest;

                            // Target is src/core/foo
                            // We need to find the file file in project that matches this
                            // But wait, the import might be checks for .js?
                            // e.g. #core/foo -> dist/core/foo.js
                            // We want to link to src/core/foo.ts

                            const targetAbs = path.resolve(process.cwd(), targetDir, cleanRest);

                            // try to find source file with extensions
                            const extensions = [".ts", ".tsx", ".d.ts"]; // assuming source is TS
                            let foundSource = null;

                            // Try exact match first (unlikely if checks for directory)
                            for (const ext of extensions) {
                                // check if targetAbs + ext is a file in project
                                // ts-morph SourceFiles are keyed by normalized path
                                const probe = targetAbs + ext;
                                const f = project.getSourceFile(probe); // naive check
                                if (f) {
                                    foundSource = f;
                                    break;
                                }

                                // Also check file system if project doesn't have it loaded
                            }

                            if (foundSource) {
                                let relativePath = path.relative(path.dirname(filePath), foundSource.getFilePath());
                                relativePath = relativePath.split(path.sep).join("/");
                                if (!relativePath.startsWith(".")) relativePath = "./" + relativePath;
                                const ext = path.extname(relativePath);
                                if (ext) relativePath = relativePath.substring(0, relativePath.length - ext.length);
                                if (relativePath.endsWith("/index")) relativePath = relativePath.substring(0, relativePath.length - 6);
                                if (relativePath === "") relativePath = ".";

                                return relativePath;
                            }
                        }
                    }
                }

                console.warn(`[WARN] Could not resolve '${specifier}' in ${filePath}`);
                return null;
            }
        };

        // Rewrites
        sourceFile.getImportDeclarations().forEach(importDecl => {
            const specifier = importDecl.getModuleSpecifierValue();
            const newSpecifier = rewrite(specifier, importDecl);
            if (newSpecifier) {
                importDecl.setModuleSpecifier(newSpecifier);
                modifications++;
            }
        });

        sourceFile.getExportDeclarations().forEach(exportDecl => {
            const specifier = exportDecl.getModuleSpecifierValue();
            if (specifier) {
                const newSpecifier = rewrite(specifier, exportDecl);
                if (newSpecifier) {
                    exportDecl.setModuleSpecifier(newSpecifier);
                    modifications++;
                }
            }
        });
    }

    if (modifications > 0) {
        console.log(`Saving ${modifications} changes...`);
        await project.save();
        console.log("Done.");
    } else {
        console.log("No changes made.");
    }
}

main().catch(err => {
    console.error(err);
    process.exit(1);
});

